/* Flash cards USMLE: Musculoskeletal (560 cartões originais). [id, pergunta, resposta, explicação em português] */
window.USMLE_DATA = window.USMLE_DATA || {};
window.USMLE_DATA["musculoskeletal"] = [{"name":"Anatomy & Physiology","cards":[["5npgrg1qb","Which muscles make up the rotator cuff?","Supraspinatus, infraspinatus, teres minor, subscapularis (SItS).","Supraespinal, infraespinal, redondo menor, subescapular."],["1m96hk63a","What does the supraspinatus do and how is it tested?","Abducts arm initially (0-15°, before deltoid); empty can test; most commonly injured rotator cuff muscle.","Abdução inicial; teste da lata vazia."],["nb63y25fn","What does the infraspinatus do?","Externally rotates the arm; injured in pitching.","Rotação externa."],["1lbail1el","What does the teres minor do?","Adducts and externally rotates the arm.","Adução e rotação externa."],["w3pyzu1xb","What does the subscapularis do?","Internally rotates and adducts the arm; lift-off test.","Rotação interna."],["1bo1lr71b","Which nerve innervates the supraspinatus and infraspinatus?","Suprascapular nerve.","Nervo supraescapular."],["14hwqq51k","Which nerve innervates the teres minor and deltoid?","Axillary nerve.","Nervo axilar."],["1bcem5m1a","Which nerve innervates the subscapularis?","Upper and lower subscapular nerves.","Nervos subescapulares."],["lmkduamq6","What injury damages the axillary nerve?","Surgical neck of humerus fracture or anterior shoulder dislocation: flattened deltoid, loss of abduction beyond 15°, loss of sensation over lateral shoulder.","Fratura do colo cirúrgico; ombro achatado."],["sy4r7b4xj","What injury damages the musculocutaneous nerve?","Upper trunk compression: loss of forearm flexion and supination, sensation over lateral forearm.","Perde flexão do cotovelo."],["1ft4amz1u","What injury damages the radial nerve?","Midshaft humerus fracture, compression of axilla (crutches, Saturday night palsy): wrist drop, loss of extension, sensation over dorsal hand.","Fratura diafisária do úmero; mão caída."],["13qpxhn1l","What injury damages the median nerve proximally?","Supracondylar fracture of humerus: loss of wrist flexion, thumb opposition, lumbricals 1-2; ape hand; pope's blessing when making a fist.","Fratura supracondiliana; mão de bênção."],["166atao18","What injury damages the median nerve distally?","Carpal tunnel syndrome, wrist laceration: thenar atrophy, loss of thumb opposition, sensory loss lateral 3.5 fingers.","Túnel do carpo; atrofia tenar."],["11jxqjp1n","What injury damages the ulnar nerve proximally?","Medial epicondyle fracture (funny bone): radial deviation of wrist on flexion, ulnar claw on digit extension (Pope's blessing variant).","Fratura do epicôndilo medial."],["1u35mim1j","What injury damages the ulnar nerve distally?","Hook of hamate fracture (Guyon canal, cyclists): ulnar claw (4th and 5th digits), loss of hypothenar and interossei.","Garra ulnar; ciclistas."],["qfsc541au","What injury damages the recurrent branch of the median nerve?","Superficial laceration of palm: loss of thenar muscle function (opposition, abduction, flexion of thumb) without sensory loss.","Perde oposição do polegar."],["87d2aocch","What causes Erb palsy?","Upper trunk (C5-C6) injury from lateral traction on the neck during delivery or trauma: waiter's tip (arm adducted, internally rotated, extended at elbow, forearm pronated).","Lesão C5-C6; gorjeta do garçom."],["1paset01h","What causes Klumpke palsy?","Lower trunk (C8-T1) injury from upward arm traction (grabbing a tree branch, delivery): total claw hand; may have Horner syndrome.","Lesão C8-T1; mão em garra total."],["3stcf93u6","What is thoracic outlet syndrome?","Compression of the lower trunk and subclavian vessels (cervical rib, Pancoast tumor): atrophy of intrinsic hand muscles, ischemia, pain, edema.","Compressão por costela cervical."],["1y3mci31l","What injury damages the long thoracic nerve?","Axillary node dissection after mastectomy or stab wounds: winged scapula (serratus anterior), inability to abduct arm above horizontal.","Escápula alada."],["14csyad4n","What forms the brachial plexus?","Roots (C5-T1), trunks, divisions, cords, branches: Randy Travis Drinks Cold Beer.","Raízes, troncos, divisões, fascículos, ramos."],["121q5jo1q","What are the boundaries of the carpal tunnel?","Flexor retinaculum (roof) and carpal bones (floor); contains median nerve and flexor tendons (not the ulnar nerve).","Contém nervo mediano e tendões flexores."],["1gwfapqh2","What are the clinical tests for carpal tunnel syndrome?","Tinel sign (percussion) and Phalen maneuver (wrist flexion).","Sinais de Tinel e Phalen."],["1fcoxgk14","What conditions are associated with carpal tunnel syndrome?","Pregnancy, rheumatoid arthritis, hypothyroidism, diabetes, acromegaly, dialysis-related amyloidosis, repetitive use.","Gestação, artrite, hipotireoidismo."],["18x6ntt1h","What is the most commonly fractured carpal bone?","Scaphoid; tenderness in anatomic snuffbox; risk of avascular necrosis and nonunion (retrograde blood supply).","Escafoide; tabaqueira anatômica."],["wg4tjjdeb","What is the most commonly dislocated carpal bone?","Lunate; can cause acute carpal tunnel syndrome.","Semilunar."],["sbsd25gu9","What is a boxer's fracture?","Fracture of the 5th metacarpal neck from punching a hard surface.","Fratura do 5º metacarpo."],["ndu00he4p","What is the function of the lumbricals?","Flex the MCP joints and extend the PIP and DIP joints.","Flexionam MCF e estendem interfalângicas."],["1axb29b1b","Which nerves innervate the lumbricals?","1st and 2nd: median nerve. 3rd and 4th: ulnar nerve.","Mediano e ulnar."],["13nbznlfq","What do the dorsal and palmar interossei do?","Dorsal: abduct fingers (DAB). Palmar: adduct fingers (PAD). Both ulnar nerve.","Dorsais abduzem; palmares aduzem."],["k4a0bl1y3","What is the lower extremity nerve injury causing foot drop?","Common fibular (peroneal) nerve injury at the fibular neck: loss of dorsiflexion and eversion; steppage gait.","Nervo fibular comum; pé caído."],["17xw87v16","What is the lower extremity nerve injury causing loss of plantarflexion?","Tibial nerve injury (knee trauma, Baker cyst): inability to plantarflex and invert, can't stand on tiptoes.","Nervo tibial."],["euy3yk5o5","What is the lower extremity nerve injury causing loss of knee extension?","Femoral nerve injury (pelvic fracture): decreased patellar reflex, loss of thigh flexion and leg extension.","Nervo femoral."],["401g6912b","What is the lower extremity nerve injury causing loss of thigh adduction?","Obturator nerve injury (pelvic surgery): decreased sensation medial thigh.","Nervo obturatório."],["1dpyu2o1p","What is the lower extremity nerve injury causing Trendelenburg sign?","Superior gluteal nerve injury (iatrogenic injection): hip drops on the contralateral side when standing on the affected leg (gluteus medius and minimus weakness).","Nervo glúteo superior; sinal de Trendelenburg."],["15d8t7vl9","What is the lower extremity nerve injury causing difficulty climbing stairs and rising from a chair?","Inferior gluteal nerve injury (posterior hip dislocation): gluteus maximus weakness.","Nervo glúteo inferior."],["119jdr51d","What is meralgia paresthetica?","Compression of the lateral femoral cutaneous nerve (tight clothing, obesity, pregnancy): pain and paresthesia of lateral thigh.","Compressão do cutâneo femoral lateral."],["19sobym1x","Where should intramuscular gluteal injections be given?","Superolateral quadrant (anterolateral) of the buttock to avoid the sciatic nerve.","Quadrante superolateral."],["17m30cndm","What is the unhappy triad of the knee?","Injury to ACL, MCL, and medial meniscus (common in contact sports with lateral force); now lateral meniscus more common.","LCA, LCM e menisco."],["r5tvfw16d","What tests assess ACL and PCL integrity?","Anterior drawer and Lachman (ACL); posterior drawer (PCL).","Gaveta anterior e Lachman."],["1bozmfyw0","What test assesses MCL and LCL?","Valgus stress (MCL) and varus stress (LCL).","Estresse em valgo e varo."],["1hz65knrx","What test assesses meniscal tears?","McMurray test (pain or popping on rotation).","Teste de McMurray."],["1jngruxs5","What is a Baker cyst?","Popliteal fluid collection (gastrocnemius-semimembranosus bursa) communicating with the knee joint, often with rheumatoid arthritis or osteoarthritis; rupture mimics DVT.","Cisto poplíteo."],["14v3w7jy7","What is prepatellar bursitis?","Inflammation of the prepatellar bursa from repetitive kneeling (housemaid's knee).","Bursite pré-patelar."],["1n3fdtt1u","What is lateral epicondylitis?","Tennis elbow: repetitive extension (backhand) or idiopathic; pain near lateral epicondyle.","Cotovelo de tenista."],["14ziw5myu","What is medial epicondylitis?","Golfer's elbow: repetitive flexion (forehand) or idiopathic; pain near medial epicondyle.","Cotovelo de golfista."],["e2xzj6n5g","What is de Quervain tenosynovitis?","Inflammation of abductor pollicis longus and extensor pollicis brevis tendons: pain at radial styloid, positive Finkelstein test; new mothers.","Tenossinovite do polegar; Finkelstein."],["1xd9x5p1o","What is a ganglion cyst?","Fluid-filled swelling overlying a joint or tendon sheath, usually dorsal wrist.","Cisto sinovial."],["kq2bq2kne","What is Dupuytren contracture?","Fibroproliferation of palmar fascia causing flexion contracture of the 4th and 5th fingers.","Contratura da fáscia palmar."],["il4p1mced","What is the most common shoulder dislocation and its nerve risk?","Anterior dislocation (axillary nerve injury).","Luxação anterior; nervo axilar."],["wy32qs1sp","What causes posterior shoulder dislocation?","Seizures or electrocution.","Convulsão ou choque elétrico."],["63z1iu1pc","What is Osgood-Schlatter disease?","Traction apophysitis of the tibial tubercle in adolescent athletes (jumping); knee pain and swelling.","Dor na tuberosidade tibial em adolescentes."],["1qrlvw31t","What is nursemaid's elbow?","Radial head subluxation in young children after sudden pull on the arm; child holds arm pronated.","Subluxação da cabeça do rádio."],["lppss412w","What is a slipped capital femoral epiphysis?","Obese adolescent with hip or knee pain and altered gait; ice cream scoop slipping off cone on x-ray.","Adolescente obeso com dor no quadril."],["1e0c3n71f","What is Legg-Calvé-Perthes disease?","Idiopathic avascular necrosis of the femoral head in boys 3-10 years; insidious painless limp.","Necrose da cabeça femoral em meninos."],["up0nulbo6","What is developmental dysplasia of the hip?","Abnormal acetabulum development; Ortolani and Barlow maneuvers; ultrasound in infants; breech babies at risk.","Displasia do quadril; Ortolani e Barlow."],["1nffywsvj","What is transient synovitis?","Self-limited hip pain and limp in children after viral illness; afebrile or low-grade fever.","Sinovite transitória após virose."],["1rk2mt4b2","What are the Kocher criteria for septic arthritis of the hip in children?","Fever, inability to bear weight, ESR >40, WBC >12,000.","Critérios de Kocher."],["iuyazw1n8","What is the sliding filament model of muscle contraction?","Myosin heads bind actin and pull thin filaments toward the M line, shortening the sarcomere.","Miosina puxa a actina."],["e7382kh3x","Which bands shorten during muscle contraction?","H and I bands shorten; A band stays the same length.","Bandas H e I encurtam."],["i2bnbh1be","What triggers skeletal muscle contraction?","AP depolarizes T tubules, dihydropyridine receptor changes conformation, ryanodine receptor releases Ca2+ from SR, Ca2+ binds troponin C, exposing myosin-binding sites on actin.","Cálcio liga troponina C."],["z8axgk132","What role does ATP play in muscle contraction?","ATP binding releases myosin from actin; ATP hydrolysis cocks the myosin head; lack of ATP causes rigor mortis.","ATP solta a miosina; falta causa rigidez."],["y4ec781q6","What is the difference between type I and type II muscle fibers?","Type I: slow twitch, red (myoglobin, mitochondria), oxidative, endurance. Type II: fast twitch, white, glycolytic, sprinting (one slow red ox).","Tipo I lento e vermelho; tipo II rápido e branco."],["1njcydw1f","How is smooth muscle contraction regulated?","Ca2+ binds calmodulin, activating myosin light-chain kinase, which phosphorylates myosin.","Calmodulina e quinase da cadeia leve."],["1yn3g2bza","How do NO and cGMP relax smooth muscle?","Activate myosin light-chain phosphatase, dephosphorylating myosin.","Fosfatase relaxa o músculo liso."],["vzh3r3p6y","What is the role of the muscle spindle?","Senses muscle stretch (length); afferent Ia fibers mediate the stretch reflex.","Detecta estiramento."],["25gr1uztb","What is the role of the Golgi tendon organ?","Senses muscle tension; inhibits contraction via Ib afferents.","Detecta tensão."],["uvroje10z","What is bone formation by endochondral ossification?","Cartilage model replaced by bone; forms axial and appendicular skeleton and base of skull.","Cartilagem vira osso; ossos longos."],["1iwe91q1z","What is intramembranous ossification?","Bone forms directly from mesenchyme without cartilage; calvarium, facial bones, clavicle.","Osso direto do mesênquima; crânio."],["6a2jop1bp","What do osteoblasts do?","Build bone by secreting collagen and catalyzing mineralization; express RANKL; alkaline phosphatase marker.","Formam osso."],["1n7avpkdb","What do osteoclasts do?","Multinucleated cells that dissolve bone by secreting H+ and collagenases; derived from monocytes; activated by RANKL.","Reabsorvem osso."],["1fdnb0n1u","What is the role of RANKL and OPG?","RANKL (from osteoblasts) binds RANK on osteoclast precursors to activate them; OPG is a decoy receptor inhibiting RANKL.","RANKL ativa osteoclastos; OPG bloqueia."],["93eu151v0","How does estrogen protect bone?","Inhibits apoptosis of osteoblasts and induces osteoclast apoptosis; deficiency increases bone resorption.","Protege osteoblastos."],["1cfv8d41i","What is the role of PTH in bone at low intermittent levels?","Anabolic: stimulates bone formation (teriparatide).","Doses intermitentes formam osso."],["myd64okaf","What is the epiphyseal growth plate?","Cartilage zone where longitudinal growth occurs; affected by achondroplasia (FGFR3) and closes with puberty (estrogen).","Placa de crescimento."],["ykywbb1n8","What are the layers of the epidermis from deep to superficial?","Stratum basale, spinosum, granulosum, lucidum, corneum (Californians Like Girls in String Bikinis, reversed).","Basal, espinhosa, granulosa, lúcida, córnea."],["ndoz7u1cx","Where are the stem cells of the epidermis?","Stratum basale.","Camada basal."],["i92oh91pd","Where are desmosomes most prominent in the epidermis?","Stratum spinosum.","Camada espinhosa."],["1x9lb47zx","What are the epithelial cell junctions in skin and their diseases?","Desmosomes (pemphigus vulgaris), hemidesmosomes (bullous pemphigoid).","Desmossomos e hemidesmossomos."],["1ohb0im19","What are melanocytes and where are they located?","Neural crest-derived cells in the stratum basale producing melanin.","Na camada basal; produzem melanina."],["14znybw1p","What are Langerhans cells in skin?","Dendritic antigen-presenting cells in the epidermis.","Células apresentadoras na epiderme."],["rjd6v31w7","What are the dermatomes of key landmarks?","C6 thumb, C7 middle finger, C8 little finger, T4 nipple, T10 umbilicus, L1 inguinal ligament, L4 knee, L5 dorsum of foot, S1 lateral foot.","Dermátomos principais."],["ydr9851kt","What are the reflexes and their roots?","Biceps C5, brachioradialis C6, triceps C7, patellar L4, Achilles S1.","Reflexos e raízes."],["1su7yis16","What is the most common site of lumbar disc herniation?","L4-L5 or L5-S1, usually posterolateral, compressing the nerve root below (e.g., L4-L5 herniation affects L5 root).","L4-L5 e L5-S1."],["1q6zmxcaf","What are the signs of L5 radiculopathy?","Weakness of dorsiflexion and great toe extension, sensory loss dorsum of foot, normal reflexes.","Fraqueza do hálux e dorso do pé."],["k671cb77b","What are the signs of S1 radiculopathy?","Weakness of plantarflexion, decreased Achilles reflex, sensory loss lateral foot.","Reflexo aquileu diminuído."],["8ga1sx1fq","What is the straight leg raise test?","Pain radiating below the knee when raising the straight leg indicates lumbar radiculopathy (sciatica).","Lasègue positivo."],["dpqfm2zpb","What is cauda equina syndrome?","Compression of lumbosacral roots: saddle anesthesia, bowel/bladder dysfunction, bilateral leg weakness, decreased reflexes; surgical emergency.","Anestesia em sela e incontinência."],["1q0uey192","What is spinal stenosis?","Narrowing of spinal canal: neurogenic claudication (pain with walking or standing, relieved by flexion, e.g., leaning on shopping cart).","Dor ao andar que melhora inclinando."],["2ey99s11e","What is spondylolisthesis?","Forward slipping of one vertebra over another; step-off on palpation.","Escorregamento vertebral."],["13h5hoqw9","What is spondylolysis?","Defect in pars interarticularis, often in adolescent athletes (gymnasts); scotty dog collar on oblique x-ray.","Defeito da pars interarticularis."],["12itmehr5","Which muscles are innervated by the femoral nerve?","Quadriceps, iliopsoas (partly), sartorius, pectineus.","Quadríceps."],["1byjcs14h","Which muscles are innervated by the sciatic nerve?","Hamstrings and, via its branches (tibial and common fibular), the leg and foot muscles.","Isquiotibiais e perna."],["u11so6176","What are the compartments of the leg and their nerves?","Anterior (deep fibular: dorsiflexion), lateral (superficial fibular: eversion), posterior (tibial: plantarflexion, inversion).","Compartimentos da perna."],["q8l457r5x","What is compartment syndrome?","Increased pressure within a fascial compartment (fractures, crush injuries, reperfusion): pain out of proportion, pain on passive stretch; treated with fasciotomy.","Dor desproporcional; fasciotomia."],["1lg7309is","Which muscle inverts and which everts the foot?","Inversion: tibialis posterior and anterior (tibial and deep fibular nerves). Eversion: fibularis longus and brevis (superficial fibular).","Tibiais invertem; fibulares evertem."],["mrirsg1ey","What is the most common ankle sprain ligament?","Anterior talofibular ligament (inversion injury).","Ligamento talofibular anterior."],["au5vrq6ag","What is a Jones fracture?","Fracture of the 5th metatarsal base (diaphysis), prone to nonunion.","Fratura do 5º metatarso."],["1g8noyt1t","What is a stress fracture's typical location in runners and military recruits?","Metatarsal shafts (march fracture), tibia.","Metatarsos e tíbia."],["mxgxqw1yp","What is the role of the anatomic snuffbox?","Contains radial artery; tenderness suggests scaphoid fracture.","Tabaqueira anatômica."],["qosx3g164","What are the 4 Ps of compartment syndrome late signs?","Pallor, paresthesias, poikilothermia, pulselessness (and paralysis); pain is earliest.","Sinais tardios; dor é o primeiro."],["1ltdlb01p","What is the structure of the hip joint's blood supply?","Medial circumflex femoral artery (main to femoral head); damage in femoral neck fracture causes avascular necrosis.","Artéria circunflexa femoral medial."],["13yf4cw1w","What is a femoral neck fracture's classic presentation?","Elderly with fall: shortened, externally rotated leg; risk of avascular necrosis.","Perna encurtada e rodada externamente."],["lgzusc11k","What is the role of the rotator cuff in shoulder stability?","Holds the humeral head in the glenoid during movement.","Estabiliza a cabeça do úmero."],["vqrp68x0w","What is the painful arc and its significance?","Pain between 60-120° abduction suggests supraspinatus tendinopathy or impingement.","Arco doloroso; impacto."],["kp6sxgcra","What is adhesive capsulitis?","Frozen shoulder: progressive pain and restriction of active and passive motion; associated with diabetes.","Ombro congelado."],["oy182i1ft","What is the trigger finger?","Stenosing tenosynovitis of flexor tendon causing finger locking in flexion.","Dedo em gatilho."],["1dl505i10","What is mallet finger?","Extensor tendon avulsion at the DIP joint causing inability to extend the distal phalanx.","Dedo em martelo."],["q0i9d51s8","What is jersey finger?","Avulsion of flexor digitorum profundus tendon from distal phalanx (ring finger).","Avulsão do flexor profundo."],["b9ri3t1vh","What is gamekeeper's (skier's) thumb?","Ulnar collateral ligament injury of the thumb MCP joint.","Lesão do ligamento colateral ulnar do polegar."],["1o1k89ftm","What is the Colles fracture?","Distal radius fracture with dorsal displacement after fall on outstretched hand (dinner fork deformity); osteoporosis.","Fratura do rádio distal; garfo."],["1obwkf5kv","What is the role of the anterior and posterior interosseous nerves?","Anterior interosseous (median): FPL, FDP lateral half, pronator quadratus; injury causes inability to make an OK sign. Posterior interosseous (radial): finger extensors.","Interósseo anterior: sinal do OK."],["gux1yr1lx","What is cubital tunnel syndrome?","Ulnar nerve compression at the elbow: numbness of 4th and 5th fingers, weakness of intrinsic hand muscles.","Compressão do ulnar no cotovelo."],["76kwwk1fz","What is Guyon canal syndrome?","Ulnar nerve compression at the wrist (cyclists): hypothenar and intrinsic weakness with sensory changes.","Ulnar no punho; ciclistas."],["1ejvh7e15","What is the function of the deltoid?","Abducts arm from 15° to 90° (axillary nerve).","Abdução de 15 a 90 graus."],["vnoe7sk9p","What muscles abduct the arm above the horizontal?","Trapezius and serratus anterior (scapular rotation).","Trapézio e serrátil anterior."],["1li829bi0","What nerve innervates the trapezius?","Spinal accessory nerve (CN XI); injury causes shoulder droop.","Nervo acessório."],["cphlyxpn4","What nerve innervates the latissimus dorsi?","Thoracodorsal nerve: extends, adducts, internally rotates the arm.","Nervo toracodorsal."],["xdcdpd1jd","What is the difference between a sprain and a strain?","Sprain: ligament injury. Strain: muscle or tendon injury.","Entorse é ligamento; distensão é músculo."],["1fytjbr9s","What are the signs of an Achilles tendon rupture?","Sudden pain (pop) during push-off, inability to plantarflex strongly, positive Thompson test (no plantarflexion with calf squeeze).","Teste de Thompson positivo."],["1nsoxlc15","Which drugs increase risk of Achilles tendon rupture?","Fluoroquinolones and corticosteroids.","Quinolonas e corticoides."],["10nr4uf18","What is plantar fasciitis?","Inflammation of the plantar aponeurosis: heel pain worse with first steps in the morning.","Dor no calcanhar ao acordar."],["1hajgf413","What is Morton neuroma?","Interdigital nerve thickening between 3rd and 4th toes: burning pain, worse with tight shoes; click on squeeze (Mulder sign).","Neuroma entre 3º e 4º dedos."],["ddqup1wp3","What is the role of synovial fluid?","Lubricates joints; analysis distinguishes noninflammatory, inflammatory, septic, and crystal arthritis.","Lubrifica; a análise define a causa."],["v4nhx7102","What synovial fluid WBC count suggests septic arthritis?","More than 50,000 cells/mm³ with mostly neutrophils.","Mais de 50.000 leucócitos."],["dosc5u156","What synovial fluid WBC count suggests noninflammatory (osteoarthritis)?","Less than 2,000 cells/mm³.","Menos de 2.000."],["470i3r1l6","What type of collagen predominates in articular cartilage?","Type II collagen.","Colágeno tipo II."],["1n8gw1h1k","What is the role of proteoglycans in cartilage?","Aggrecan retains water, providing compressive resistance.","Retêm água."],["cksh1ar72","What is avascular necrosis's most common sites?","Femoral head, scaphoid, talus.","Cabeça femoral, escafoide, tálus."],["1r3tigdxq","What are causes of avascular necrosis?","Corticosteroids, alcohol, sickle cell disease, trauma, SLE, Gaucher disease, caisson disease, Legg-Calvé-Perthes.","Corticoide, álcool, falciforme, trauma."],["um1hbm100","What is the earliest imaging finding in avascular necrosis?","MRI changes (x-ray normal early).","Ressonância detecta cedo."],["180i3j015","What is the role of vitamin D and calcium in bone?","Mineralization of osteoid; deficiency causes rickets/osteomalacia.","Mineralização do osso."],["11q0zaw1q","What is a sarcomere's Z line?","Boundary of the sarcomere where actin filaments anchor.","Limite do sarcômero."],["1j7dogw57","What is the role of titin?","Giant protein anchoring myosin to the Z line, providing elasticity.","Dá elasticidade ao sarcômero."],["1aqt4tswa","What is the role of dystrophin in muscle?","Links actin cytoskeleton to the extracellular matrix via dystroglycan complex.","Liga o citoesqueleto à matriz."],["aa9hksm1i","What is the role of the T tubule?","Invagination of the sarcolemma conducting action potentials into the muscle fiber.","Conduz o potencial para dentro da fibra."],["1si0ilh1i","What is the role of calsequestrin?","Calcium-binding protein storing Ca2+ in the sarcoplasmic reticulum.","Armazena cálcio no retículo."],["f9wnvp12c","What happens in malignant hyperthermia?","Mutation in ryanodine receptor (RYR1) causes uncontrolled Ca2+ release with inhaled anesthetics or succinylcholine: hyperthermia, rigidity, rhabdomyolysis, hypercarbia; treat with dantrolene.","Mutação RYR1; dantroleno."],["dchmjj15h","What is rhabdomyolysis?","Muscle breakdown (trauma, exertion, drugs, statins, seizures): high CK, myoglobinuria (dark urine, positive blood on dipstick without RBCs), AKI, hyperkalemia.","CPK alta, urina escura, lesão renal."],["1xorybv7b","What is the treatment of rhabdomyolysis?","Aggressive IV fluids; correct electrolytes.","Hidratação vigorosa."],["c9yjrso6e","What muscles are involved in hip flexion?","Iliopsoas (main), rectus femoris, sartorius.","Iliopsoas."],["5b48h87ch","What muscle extends the hip?","Gluteus maximus (and hamstrings).","Glúteo máximo."],["1c4vdlb1e","What muscles abduct the hip?","Gluteus medius and minimus (superior gluteal nerve).","Glúteo médio e mínimo."],["18y67k91l","What muscles adduct the hip?","Adductor longus, brevis, magnus, gracilis (obturator nerve).","Adutores."],["qwdfxu1sa","What is the course of the sciatic nerve?","Exits through greater sciatic foramen below piriformis, descends in posterior thigh, divides into tibial and common fibular nerves above the knee.","Abaixo do piriforme; divide-se acima do joelho."],["c17bpt12k","What is piriformis syndrome?","Compression of sciatic nerve by the piriformis muscle causing buttock pain and sciatica.","Piriforme comprime o ciático."],["1p8856n1i","What is the pes anserinus?","Insertion of sartorius, gracilis, semitendinosus on medial tibia; site of bursitis.","Pata de ganso."],["lth5n253t","What is iliotibial band syndrome?","Lateral knee pain in runners from friction of the IT band over the lateral femoral epicondyle.","Dor lateral do joelho em corredores."],["13fepfccg","What is patellofemoral pain syndrome?","Anterior knee pain in young athletes, worse with stairs, squatting, prolonged sitting.","Dor anterior do joelho."],["kfq9gh1q3","What is the role of the menisci?","Fibrocartilage pads distributing load and stabilizing the knee.","Distribuem carga no joelho."],["1u8we6xt7","What is the role of the ACL?","Prevents anterior translation of the tibia on the femur.","Impede o deslizamento anterior da tíbia."],["1u97zu0t7","What is the role of the PCL?","Prevents posterior translation of the tibia on the femur.","Impede o deslizamento posterior."],["1xk8qdi17","What is the typical mechanism of ACL injury?","Noncontact pivoting or sudden deceleration with a pop and rapid effusion (hemarthrosis).","Giro brusco com estalo e inchaço."],["1faqcd314","What is the typical mechanism of PCL injury?","Dashboard injury (posterior force on flexed knee).","Trauma no painel do carro."],["18hhb0869","What are the muscles of the anterior arm and their nerve?","Biceps, brachialis, coracobrachialis (musculocutaneous nerve): flex the elbow.","Bíceps; nervo musculocutâneo."],["1s7595s35","What muscle is the main forearm supinator?","Biceps brachii (when elbow flexed) and supinator.","Bíceps."],["14nfln0x0","What are the boundaries and contents of the cubital fossa?","Contains (lateral to medial) biceps tendon, brachial artery, median nerve.","Tendão do bíceps, artéria braquial, mediano."],["lvrlvd1kz","What is the blood supply of the hand?","Superficial palmar arch (ulnar artery) and deep palmar arch (radial artery).","Arcos palmares."],["7vd5kf10k","What is the Allen test?","Assesses collateral circulation of the hand via ulnar and radial arteries before radial artery procedures.","Avalia circulação colateral da mão."],["1nloymw17","What are the muscles of the thenar eminence and their nerve?","Opponens pollicis, abductor pollicis brevis, flexor pollicis brevis (recurrent branch of median nerve).","Músculos tenares; nervo mediano."],["dh67o6gcn","What are the muscles of the hypothenar eminence and their nerve?","Opponens digiti minimi, abductor digiti minimi, flexor digiti minimi brevis (ulnar nerve).","Músculos hipotenares; nervo ulnar."],["48mvw7bcr","Which nerve gives sensation to the medial 1.5 fingers?","Ulnar nerve.","Nervo ulnar."],["1uk8xrypp","Which nerve gives sensation to the dorsal first web space?","Radial nerve (superficial branch).","Nervo radial."],["c9izr51f4","Which muscle is the main hip flexor and which nerve supplies it?","Iliopsoas (femoral nerve and L1-L3 branches).","Iliopsoas."],["3nlc4rvhx","What is the femoral triangle order from lateral to medial?","Nerve, Artery, Vein, Empty space, Lymphatics (NAVEL).","Nervo, artéria, veia, espaço, linfáticos."],["1akf9rgb6","Where is the femoral pulse palpated?","Midinguinal point, below the inguinal ligament.","Abaixo do ligamento inguinal."],["cp5n6i12a","What is the popliteal fossa's deepest structure?","Popliteal artery (deepest), then vein, then tibial nerve most superficial.","Artéria poplítea é a mais profunda."],["axfgg31d5","What is the dorsalis pedis artery's palpation site?","Lateral to the extensor hallucis longus tendon on the dorsum of the foot.","Dorso do pé."],["jd29jmezp","Where is the posterior tibial pulse palpated?","Behind the medial malleolus.","Atrás do maléolo medial."],["1tpin97fo","What is the role of the quadriceps tendon and patellar ligament?","Transmit quadriceps force to extend the knee via the tibial tuberosity.","Extensão do joelho."],["1ozc6c51p","What is the role of the hamstrings?","Flex the knee and extend the hip (tibial division of sciatic nerve).","Flexão do joelho e extensão do quadril."],["1wo82i7rb","What is the function of the gastrocnemius and soleus?","Plantarflexion via the Achilles tendon (tibial nerve).","Flexão plantar."],["3m6rco1k3","What is the function of the tibialis anterior?","Dorsiflexion and inversion of the foot (deep fibular nerve).","Dorsiflexão."],["ecx6o3334","What is the role of the intervertebral disc's nucleus pulposus?","Gel-like shock absorber derived from the notochord; herniates through the annulus fibrosus.","Amortecedor; hernia pelo ânulo."],["1h4nqjdgs","Why do lumbar disc herniations usually go posterolateral?","The posterior longitudinal ligament is thin laterally and strong in the midline.","Ligamento posterior mais fraco lateralmente."],["5ic0na1rg","What is the C5-C6 root's motor function?","Shoulder abduction (C5) and elbow flexion, wrist extension (C6).","Abdução do ombro e flexão do cotovelo."],["sumpvc1m3","What is the motor function of the C7 root?","Elbow extension (triceps) and wrist flexion.","Extensão do cotovelo."],["1igynxo1a","What is the motor function of the C8-T1 roots?","Finger flexion and hand intrinsic muscles.","Flexão dos dedos e intrínsecos."]]},{"name":"Pathology (Part 1)","cards":[["2kucub1qs","What is osteoporosis?","Trabecular (spongy) and cortical bone lose mass despite normal mineralization and lab values (Ca2+, phosphate, PTH, ALP normal).","Perda de massa óssea com exames normais."],["tme1qs852","What are the types of osteoporosis?","Primary: postmenopausal (increased resorption from low estrogen) and senile (age-related). Secondary: drugs (steroids, anticonvulsants, heparin, PPIs), hyperparathyroidism, hyperthyroidism, alcohol, immobilization.","Pós-menopausa, senil ou secundária."],["kmrko1479","How is osteoporosis diagnosed?","DEXA scan T-score ≤ -2.5, or fragility fracture (hip, vertebra) regardless of T-score.","T-score ≤ -2,5 na densitometria."],["i791wbkj6","Who should be screened for osteoporosis?","Women ≥65 years, or younger postmenopausal women with risk factors.","Mulheres a partir de 65 anos."],["189kcli9s","What are the complications of osteoporosis?","Vertebral compression fractures (acute back pain, loss of height, kyphosis), hip fractures, distal radius (Colles) fractures.","Fraturas vertebrais, de quadril e punho."],["h9o7dqysh","Treatment of osteoporosis?","Calcium, vitamin D, weight-bearing exercise; bisphosphonates; denosumab; teriparatide or abaloparatide; romosozumab; raloxifene.","Cálcio, vitamina D, bisfosfonatos."],["1jx7ovxkr","What is osteopetrosis?","Failure of normal bone resorption due to defective osteoclasts (carbonic anhydrase II mutation): thickened dense bones that are prone to fracture.","Osteoclastos falham; ossos densos e frágeis."],["1qaytsc1l","Clinical features of osteopetrosis?","Bone marrow crowding (pancytopenia, extramedullary hematopoiesis), cranial nerve impingement (vision and hearing loss), renal tubular acidosis (CA II), bone-in-bone on x-ray.","Pancitopenia e compressão de nervos."],["1tilc1s14","Treatment of osteopetrosis?","Bone marrow transplant (osteoclasts derive from monocytes).","Transplante de medula."],["1bxpuu4w8","What is osteomalacia/rickets?","Defective mineralization of osteoid (osteomalacia) or cartilaginous growth plates (rickets) due to vitamin D deficiency.","Falha na mineralização por falta de vitamina D."],["wtwsqm1td","Clinical features of rickets in children?","Pigeon breast, frontal bossing, rachitic rosary (costochondral junction thickening), bowed legs (genu varum), craniotabes.","Rosário raquítico e pernas arqueadas."],["9c7lccbgn","Lab findings in osteomalacia?","Low vitamin D, low calcium, low phosphate, high PTH, high alkaline phosphatase.","Vitamina D, cálcio e fosfato baixos; PTH e FA altos."],["16v9e9auv","What is Paget disease of bone (osteitis deformans)?","Localized disorder of bone remodeling from increased osteoclast activity followed by osteoblastic activity, forming poor-quality bone; mosaic pattern of lamellar bone.","Remodelação óssea desordenada."],["18h4its10","Clinical features of Paget disease?","Bone pain, increased hat size, hearing loss (auditory foramen narrowing), lion-like facies, isolated high alkaline phosphatase with normal Ca and phosphate.","Chapéu aumenta, surdez, FA isolada alta."],["wt0vr5n93","Complications of Paget disease?","High-output heart failure (AV shunts), osteosarcoma, fractures.","Insuficiência cardíaca de alto débito e osteossarcoma."],["5on78c1cm","Treatment of Paget disease?","Bisphosphonates (calcitonin alternative).","Bisfosfonatos."],["1xobxv81b","What is fibrous dysplasia?","Bone replaced by fibroblasts, collagen, and irregular bony trabeculae; Chinese letter or ground-glass on x-ray; GNAS mutation.","Osso trocado por tecido fibroso."],["1goxrqm1p","What is McCune-Albright syndrome?","Polyostotic fibrous dysplasia, unilateral café-au-lait spots with coast of Maine border, endocrine abnormalities (precocious puberty).","Displasia fibrosa, manchas café com leite, puberdade precoce."],["19hz3eg15","What is osteogenesis imperfecta's bone feature?","Fragile bones with multiple fractures from defective type I collagen; blue sclerae.","Ossos frágeis e escleras azuis."],["1frvy01kq","What is achondroplasia's bone feature?","Failure of longitudinal bone growth (endochondral) with normal intramembranous ossification: short limbs, normal head and trunk.","Membros curtos com cabeça normal."],["flslbjfqf","What is the most common primary malignant bone tumor in children?","Osteosarcoma.","Osteossarcoma."],["1112oza1b","Features of osteosarcoma?","Metaphysis of long bones (distal femur, proximal tibia), Codman triangle (periosteal elevation) and sunburst pattern on x-ray; risk factors: Paget, bone infarcts, radiation, familial retinoblastoma, Li-Fraumeni.","Metáfise; triângulo de Codman e raios de sol."],["flwgtioqg","Features of Ewing sarcoma?","Diaphysis of long bones (femur), pelvis, scapula, ribs in boys <15; onion skin periosteal reaction; small round blue cells; t(11;22) EWS-FLI1; responds to chemotherapy.","Diáfise; casca de cebola; t(11;22)."],["i56yqv160","Features of chondrosarcoma?","Malignant cartilage tumor of pelvis and proximal femur in adults; may arise from osteochondroma.","Tumor de cartilagem em adultos."],["qe89x49bp","What is an osteochondroma?","Most common benign bone tumor: cartilage-capped bony outgrowth of the metaphysis contiguous with the marrow; rarely transforms to chondrosarcoma.","Tumor benigno ósseo mais comum."],["14ygw6c1b","What is an osteoid osteoma?","Benign tumor of interlacing trabeculae <2 cm, in young men; bone pain worse at night relieved by NSAIDs; radiolucent nidus with sclerotic rim.","Dor noturna que melhora com AINE."],["1fugotofn","What is an osteoblastoma?","Larger (>2 cm) version of osteoid osteoma, in vertebrae; pain not relieved by NSAIDs.","Maior, na coluna, não melhora com AINE."],["el61ty1k5","What is a giant cell tumor of bone?","Locally aggressive benign tumor at the epiphysis (often around the knee) in adults 20-40; soap bubble appearance; multinucleated giant cells (RANKL); treated with denosumab or surgery.","Epífise; bolhas de sabão."],["1u4nlbl5v","What is an enchondroma?","Benign cartilage tumor in the medullary cavity of small bones of hands and feet.","Tumor de cartilagem dos dedos."],["t0z7a01lm","What is a unicameral (simple) bone cyst?","Fluid-filled benign cyst in metaphysis of long bones in children; fallen fragment sign after fracture.","Cisto ósseo simples em crianças."],["ge741l1j2","What is an aneurysmal bone cyst?","Expansile blood-filled cyst in metaphysis of long bones and vertebrae in adolescents.","Cisto com sangue expansivo."],["1a6ncub1e","What is the most common bone tumor overall?","Metastasis (breast, prostate, lung, thyroid, kidney).","Metástase."],["1qhp2l0pd","Which metastases are osteoblastic (sclerotic)?","Prostate cancer (and small cell lung cancer, some breast).","Próstata."],["143zuti1o","Which metastases are osteolytic?","Lung (non-small cell), thyroid, kidney, melanoma, multiple myeloma.","Pulmão, tireoide, rim, mieloma."],["1uiw76jor","What is the pattern of multiple myeloma bone lesions?","Punched-out lytic lesions (skull), normal bone scan (no osteoblastic activity).","Lesões líticas em saca-bocado."],["6vm0sygnl","What is osteoarthritis?","Mechanical wear and tear destroying articular cartilage: joint pain worse with use, morning stiffness <30 minutes, crepitus.","Desgaste articular; rigidez curta."],["z3zmbk1pv","Joint involvement in osteoarthritis?","Weight-bearing joints (hips, knees), DIP (Heberden nodes), PIP (Bouchard nodes), first CMC; spares MCP and wrist.","Interfalângicas distais e articulações de carga."],["1jwtnt84w","X-ray findings in osteoarthritis?","Asymmetric joint space narrowing, subchondral sclerosis and cysts, osteophytes (bone spurs), eburnation.","Osteófitos e esclerose subcondral."],["70n5qnhsu","Treatment of osteoarthritis?","Weight loss, exercise, acetaminophen, NSAIDs, intra-articular steroids, joint replacement.","Perda de peso, exercício, analgésicos."],["7z2mxsesh","What is rheumatoid arthritis?","Autoimmune inflammatory synovitis (pannus) causing erosion of cartilage and bone; HLA-DR4; rheumatoid factor and anti-CCP.","Sinovite autoimune com pannus."],["13b6zqqv1","Joint involvement in rheumatoid arthritis?","Symmetric polyarthritis of MCP, PIP, wrist; spares DIP; morning stiffness >1 hour improving with use.","Mãos simétricas, poupa interfalângicas distais."],["dl7nhrc17","Hand deformities of rheumatoid arthritis?","Ulnar deviation, swan neck, boutonnière, Z-thumb.","Desvio ulnar, pescoço de cisne, botoeira."],["11rbsjs9y","Extra-articular manifestations of rheumatoid arthritis?","Rheumatoid nodules (fibrinoid necrosis with palisading histiocytes), pleuritis, pericarditis, interstitial lung disease, scleritis, anemia of chronic disease, vasculitis.","Nódulos reumatoides e doença pulmonar."],["j13i651z0","What is Felty syndrome?","Rheumatoid arthritis, splenomegaly, neutropenia.","Artrite, esplenomegalia e neutropenia."],["1jkgafidj","What is Caplan syndrome?","Rheumatoid arthritis with pneumoconiosis and intrapulmonary nodules.","Artrite com pneumoconiose."],["10lrppk1p","What cervical spine complication occurs in rheumatoid arthritis?","Atlantoaxial subluxation (C1-C2 instability); risk during intubation.","Instabilidade atlantoaxial."],["3lvmnyid4","X-ray findings in rheumatoid arthritis?","Periarticular osteopenia, joint space narrowing (symmetric), marginal erosions.","Osteopenia e erosões marginais."],["1daw8fx1c","Treatment of rheumatoid arthritis?","DMARDs (methotrexate first line, sulfasalazine, hydroxychloroquine, leflunomide), biologics (anti-TNF, rituximab, abatacept, tocilizumab), JAK inhibitors; NSAIDs and steroids for symptoms.","Metotrexato e biológicos."],["vxj3vn1vn","What is gout?","Monosodium urate crystal deposition from hyperuricemia (underexcretion more common than overproduction).","Depósito de cristais de urato."],["gv0p7s1gu","Crystal appearance in gout?","Needle-shaped, negatively birefringent crystals (yellow when parallel to the light axis).","Agulhas com birrefringência negativa."],["u2gnoyeyj","Clinical features of gout?","Acute painful monoarthritis, often first MTP (podagra); tophi in chronic gout; triggered by alcohol, high-purine foods, dehydration, diuretics.","Dor intensa no hálux."],["qk1s7wh2r","Causes of hyperuricemia by underexcretion?","Renal failure, thiazides and loop diuretics, low-dose aspirin, alcohol, lead, cyclosporine.","Doença renal e diuréticos."],["wkgoz01p5","Causes of hyperuricemia by overproduction?","Lesch-Nyhan syndrome, PRPP excess, tumor lysis syndrome, von Gierke disease, myeloproliferative disorders, psoriasis.","Lise tumoral e Lesch-Nyhan."],["17x9ot81q","X-ray finding in chronic gout?","Punched-out erosions with overhanging edges (rat bite).","Erosões em mordida de rato."],["69y4jhe3j","What is pseudogout (CPPD)?","Calcium pyrophosphate deposition: rhomboid-shaped, weakly positively birefringent crystals; chondrocalcinosis; knee most common.","Cristais romboides positivos; condrocalcinose."],["d9w4923r5","Diseases associated with pseudogout?","Hemochromatosis, hyperparathyroidism, hypophosphatasia, hypomagnesemia, osteoarthritis.","Hemocromatose e hiperparatireoidismo."],["182h1jcg9","What is septic arthritis?","Joint infection, usually S. aureus (gonococcus in sexually active young adults): acute monoarticular swelling, warmth, pain, fever; WBC >50,000.","Infecção articular."],["mv5eh7k3e","What is reactive arthritis?","Conjunctivitis, urethritis, arthritis after GI or chlamydial infection; HLA-B27. Can't see, can't pee, can't climb a tree.","Conjuntivite, uretrite e artrite."],["16tpvxp1x","What is Lyme arthritis?","Late Lyme disease with migratory then monoarticular arthritis of large joints (knee).","Artrite do joelho na doença de Lyme."],["13umxp51e","What is neuropathic (Charcot) joint?","Joint destruction from loss of sensation and proprioception (diabetes, tabes dorsalis, syringomyelia).","Articulação destruída por neuropatia."],["kjb6tffj5","What is hemarthrosis associated with?","Hemophilia, trauma, anticoagulation.","Hemofilia e trauma."],["1t3i1r01q","What is osteomyelitis's x-ray finding?","Periosteal reaction and lytic lesions (may be normal early; MRI more sensitive).","Reação periosteal."],["9arclwevx","What is a sequestrum and involucrum?","Sequestrum: dead bone in chronic osteomyelitis. Involucrum: new reactive bone surrounding it.","Osso morto e osso novo ao redor."],["wylwazgvg","What is Brodie abscess?","Subacute osteomyelitis forming a walled-off intraosseous abscess.","Abscesso ósseo crônico."],["8kbkzprij","What is the classic findings of bone metastasis with hypercalcemia?","Osteolytic metastases from breast, lung, myeloma; PTHrP secretion from squamous cell carcinoma.","Metástases líticas e PTHrP."],["16ka1n2m5","What is the most common site of osteosarcoma?","Distal femur and proximal tibia (around the knee).","Ao redor do joelho."],["15051e319","What is the bone tumor with 'soap bubble' appearance?","Giant cell tumor (also aneurysmal bone cyst).","Tumor de células gigantes."],["32i3x3em9","What is the bone tumor with 'onion skin' periosteal reaction?","Ewing sarcoma.","Sarcoma de Ewing."],["1reup7n10","What is the bone tumor with 'sunburst' and Codman triangle?","Osteosarcoma.","Osteossarcoma."],["6bkbd5eli","What is the bone tumor with night pain relieved by aspirin?","Osteoid osteoma.","Osteoma osteoide."],["xaknc5jaa","Which bone tumor arises in the epiphysis?","Giant cell tumor (and chondroblastoma).","Tumor de células gigantes."],["lza8r9119","Which bone tumor arises in the diaphysis?","Ewing sarcoma.","Sarcoma de Ewing."],["11js4g4dc","Which bone tumors arise in the metaphysis?","Osteosarcoma and osteochondroma.","Osteossarcoma e osteocondroma."],["1iqkm4vv9","What is primary hypertrophic osteoarthropathy?","Clubbing and periostitis of long bones, often secondary to lung cancer (hypertrophic pulmonary osteoarthropathy).","Baqueteamento e periostite."],["hebfl33x4","What is avascular necrosis's typical patient?","Corticosteroid users, alcoholics, sickle cell disease, SLE patients.","Corticoide, álcool, falciforme."],["1ip0nbotp","What is the earliest sign of avascular necrosis of femoral head on imaging?","MRI changes (x-ray often normal early); later crescent sign.","Ressonância; sinal do crescente depois."],["1vajl7e1e","What is the cause of chondrocalcinosis on x-ray?","CPPD deposition (pseudogout).","Pseudogota."],["1xzjhnhp3","What is diffuse idiopathic skeletal hyperostosis?","Flowing calcification along the anterior longitudinal ligament of at least 4 vertebrae, sparing disc spaces and sacroiliac joints; elderly, diabetic.","Calcificação do ligamento longitudinal anterior."],["w38e10lis","What is the difference between osteopenia and osteoporosis on DEXA?","Osteopenia: T-score between -1 and -2.5; osteoporosis: ≤ -2.5.","Osteopenia entre -1 e -2,5."],["14r3ufcyi","What is a Z-score used for in DEXA?","Compares to age-matched controls; used in premenopausal women, men <50, children.","Comparação com mesma idade."],["vrh1222xe","What is renal osteodystrophy?","Bone disease from CKD: secondary hyperparathyroidism, osteomalacia, adynamic bone disease.","Doença óssea da insuficiência renal."],["6v8hinoku","What is the bone finding of hyperparathyroidism?","Osteitis fibrosa cystica: subperiosteal resorption (radial aspect of middle phalanges), salt-and-pepper skull, brown tumors.","Reabsorção subperiosteal e tumores marrons."],["6d20tz1cp","What is hypophosphatasia?","Deficient tissue-nonspecific alkaline phosphatase causing poor mineralization; low ALP.","Fosfatase alcalina baixa."],["1nnjkxv1b","What is the difference between OA and RA morning stiffness?","OA: <30 minutes. RA: >1 hour.","Artrose curta; artrite reumatoide longa."],["hocptd1ek","What is the difference between OA and RA in DIP involvement?","OA involves DIP (Heberden); RA spares DIP.","Artrose atinge a distal; AR poupa."],["1ht9jnw1d","What is the role of anti-CCP in rheumatoid arthritis?","Highly specific marker; appears early; predicts erosive disease.","Muito específico e prognóstico."],["eh6fhw1gb","What lab abnormality is seen in active RA?","Elevated ESR and CRP; anemia of chronic disease.","VHS e PCR altas."],["1t9rhz21d","What is juvenile idiopathic arthritis?","Arthritis in children <16 lasting >6 weeks; oligoarticular (ANA-positive, uveitis risk), polyarticular, systemic (Still disease: fever, salmon rash).","Artrite crônica na criança."],["1th6haoa7","Why do children with oligoarticular JIA need eye exams?","Risk of asymptomatic anterior uveitis (ANA positive).","Risco de uveíte silenciosa."],["13ebwpa1a","What is adult-onset Still disease?","Quotidian fever, salmon-colored evanescent rash, arthritis, very high ferritin, leukocytosis.","Febre diária, exantema salmão, ferritina alta."],["11k9ykvue","What is polymyalgia rheumatica?","Pain and stiffness of shoulders and hips in adults >50, high ESR, normal CK; associated with giant cell arteritis; responds rapidly to low-dose prednisone.","Dor nas cinturas; responde a corticoide."],["1q4insc1e","What is fibromyalgia?","Chronic widespread musculoskeletal pain with fatigue, sleep disturbance, cognitive issues; normal labs; treat with exercise, antidepressants (TCAs, SNRIs), pregabalin.","Dor difusa crônica com exames normais."],["i0tz4h1sq","What is the treatment of acute gout?","NSAIDs (indomethacin), glucocorticoids, colchicine.","AINE, corticoide ou colchicina."],["cuqrj217i","What is the long-term treatment of gout?","Xanthine oxidase inhibitors (allopurinol, febuxostat), probenecid (uricosuric), pegloticase.","Alopurinol."],["5nzhwa1ab","Why should allopurinol not be started during an acute gout flare (classic teaching)?","Rapid change in urate levels can precipitate or prolong flares; now often started with prophylaxis.","Pode piorar a crise."],["qih5hz115","What is the gout prophylaxis when starting urate-lowering therapy?","Low-dose colchicine or NSAID for several months.","Colchicina em baixa dose."],["mqgp5a104","What is tophaceous gout?","Chronic gout with urate deposits (tophi) in ears, olecranon bursa, Achilles tendon.","Tofos nas orelhas e cotovelos."],["1u8ppdwd3","What is the role of joint aspiration in acute monoarthritis?","Distinguishes septic arthritis from crystal disease (Gram stain, culture, crystals, WBC).","Diferencia infecção de cristais."],["3uejr7f3x","What is the gold standard for diagnosing gout?","Synovial fluid analysis showing monosodium urate crystals.","Cristais no líquido sinovial."],["1q8y5b4py","Why may serum uric acid be normal during a gout attack?","Levels can fall during acute flares.","Pode cair durante a crise."],["cnf5yp171","What is the classic patient with septic arthritis from gonococcus?","Sexually active young adult with migratory polyarthralgia, tenosynovitis, pustular skin lesions.","Jovem com tenossinovite e pústulas."],["1aa1pqk12","What causes osteomyelitis of the vertebrae in elderly men after UTI?","E. coli and other gram-negatives (and S. aureus).","E. coli e S. aureus."],["14evtzqov","What is the treatment of a femoral neck fracture in an elderly patient?","Surgical repair (hemiarthroplasty or total hip arthroplasty) due to avascular necrosis risk.","Artroplastia."],["36w2936n6","What is osteitis condensans ilii?","Benign sclerosis of the ilium near the SI joint in multiparous women.","Esclerose benigna do ilíaco."],["1fdzlpy17","What is the most common cause of a pathologic fracture in elderly?","Osteoporosis (then metastases).","Osteoporose."],["xrwdx6rur","What is the most common cause of low back pain?","Mechanical (musculoligamentous strain); usually self-limited.","Causa mecânica."],["1t73oc0x7","What are red flags in back pain?","Age >50, cancer history, weight loss, fever, IV drug use, night pain, neurologic deficits, bowel/bladder dysfunction, trauma, steroid use.","Sinais de alerta na lombalgia."],["lu7ogxvs6","What is the classic imaging of metastatic prostate cancer to spine?","Ivory vertebra (osteoblastic), elevated alkaline phosphatase.","Vértebra de marfim."],["1lak11y2v","What is a codfish vertebra?","Biconcave vertebral bodies from osteoporosis or sickle cell disease.","Vértebra bicôncava."],["1r3q6i014","What is a 'rugger jersey' spine?","Alternating sclerotic bands in vertebrae from renal osteodystrophy.","Faixas escleróticas na doença renal."],["rxxtwm1gq","What is a 'bamboo spine'?","Fused vertebrae from ankylosing spondylitis (syndesmophytes).","Espondilite anquilosante."],["19f6af88m","What is a 'pencil-in-cup' deformity?","Psoriatic arthritis DIP erosion.","Artrite psoriásica."],["15bidde18","What is the cause of hypertrophic osteoarthropathy?","Paraneoplastic or chronic hypoxia: clubbing, periostitis, arthritis.","Câncer de pulmão ou hipóxia crônica."],["147lx0z1j","What is myositis ossificans?","Heterotopic bone formation in muscle after trauma (eggshell calcification).","Ossificação no músculo após trauma."],["156h7631h","What is the difference between primary and secondary osteoarthritis?","Primary: idiopathic, aging. Secondary: trauma, obesity, prior joint disease, hemochromatosis, crystal disease.","Idiopática ou secundária."],["d8tt9ckx2","What is the pathogenesis of osteoarthritis?","Chondrocyte-mediated cartilage degradation (MMPs, IL-1), loss of proteoglycans, subchondral bone changes.","Degradação da cartilagem."],["1wegbvp1n","What are the classic findings of hemochromatosis arthropathy?","Second and third MCP joint arthritis with hook-like osteophytes; chondrocalcinosis.","MCF 2 e 3 com osteófitos em gancho."],["19xhb8j14","What is the triad of tuberculous arthritis/spine?","Pott disease: back pain, gibbus deformity, neurologic deficits.","Dor, giba e déficit neurológico."],["6nzvg6sv2","What is the typical age of osteosarcoma vs Ewing sarcoma?","Osteosarcoma: adolescents (and elderly). Ewing: children and adolescents <15-20.","Ambos em adolescentes."],["uvmloqcl9","What is the prognosis of Ewing sarcoma?","Aggressive with early metastases but responsive to chemotherapy.","Agressivo, mas responde à quimioterapia."],["dxvc481fy","What is a multiple hereditary exostoses syndrome?","Autosomal dominant EXT1/EXT2 mutations causing multiple osteochondromas, with increased chondrosarcoma risk.","Múltiplos osteocondromas."],["1bvh8tz6i","What is Ollier disease?","Multiple enchondromas (enchondromatosis); risk of chondrosarcoma.","Múltiplos encondromas."],["1nuhgj31t","What is Maffucci syndrome?","Multiple enchondromas with soft tissue hemangiomas; increased malignancy risk.","Encondromas com hemangiomas."],["ocl2q1suq","What is the best imaging for bone metastases?","Bone scan (except myeloma, which needs skeletal survey or MRI/PET).","Cintilografia óssea."],["941s8v5rf","What is the treatment of osteoid osteoma?","NSAIDs; radiofrequency ablation for refractory pain.","AINE ou ablação."],["8ecfkio8w","What is the cause of bone pain and pathologic fractures in a patient on long-term dialysis?","Renal osteodystrophy and beta-2 microglobulin amyloidosis.","Osteodistrofia renal."],["6r7qt6ug8","What is the bone disease associated with hypervitaminosis A?","Bone pain, hypercalcemia, premature epiphyseal closure.","Dor óssea e hipercalcemia."],["kusdwj1ru","What is the most common joint affected by gout after the first MTP?","Ankle, knee, midfoot.","Tornozelo e joelho."],["11b3vj8ki","What is the role of dual-energy CT in gout?","Detects urate deposits noninvasively.","Detecta depósitos de urato."],["nguvzx15y","What is the association between psoriasis and gout?","Increased cell turnover in psoriasis increases uric acid production.","Psoríase aumenta ácido úrico."],["fduwnw1nw","What is the treatment of septic arthritis?","Joint drainage (aspiration or surgical washout) plus IV antibiotics (vancomycin plus ceftriaxone empirically).","Drenagem e antibiótico venoso."],["1qdcrmprn","What is a prosthetic joint infection's most common organism?","Coagulase-negative staphylococci (early) and S. aureus.","Estafilococos."],["51lfbb9jj","What is the role of ESR and CRP in rheumatology?","Nonspecific inflammatory markers used to monitor disease activity.","Marcadores inespecíficos de inflamação."],["155ue1j14","What is rheumatoid factor?","IgM antibody against the Fc portion of IgG; positive in RA but also other diseases (Sjögren, hepatitis C, endocarditis).","IgM contra IgG."],["dtoxqwmvc","What is the most common cause of polyarticular arthritis in a young woman with photosensitive rash?","Systemic lupus erythematosus.","Lúpus."],["1v1gpx81x","What is a Heberden node?","Bony enlargement of the DIP joint in osteoarthritis.","Nódulo na interfalângica distal."],["1xb2ynj6h","What is a Bouchard node?","Bony enlargement of the PIP joint in osteoarthritis.","Nódulo na interfalângica proximal."],["1y2nq40dd","What is a swan neck deformity?","PIP hyperextension and DIP flexion in rheumatoid arthritis.","Hiperextensão da proximal e flexão da distal."],["1hdcxjh1u","What is a boutonnière deformity?","PIP flexion and DIP hyperextension in rheumatoid arthritis.","Flexão da proximal e extensão da distal."],["z6pojdelz","What is the X-ray finding of osteomyelitis in a diabetic foot?","Cortical destruction and periosteal reaction; MRI or probe-to-bone test helps diagnosis.","Destruição cortical."],["bu5qc4ol9","What is the treatment of chronic osteomyelitis?","Surgical debridement of dead bone plus prolonged antibiotics.","Desbridamento e antibiótico prolongado."]]},{"name":"Pathology (Part 2)","cards":[["15z4fjdka","What are seronegative spondyloarthritides?","Arthritis without rheumatoid factor, associated with HLA-B27: psoriatic arthritis, ankylosing spondylitis, IBD-associated arthritis, reactive arthritis (PAIR).","Artrites soronegativas ligadas ao HLA-B27."],["1eh669f1v","What is ankylosing spondylitis?","Chronic inflammatory disease of spine and sacroiliac joints in young men: inflammatory back pain worse in morning, improves with exercise; bamboo spine.","Lombalgia inflamatória em homem jovem."],["zpeyt91fc","Extra-articular features of ankylosing spondylitis?","Anterior uveitis, aortitis and aortic regurgitation, restrictive lung disease (costovertebral fusion), enthesitis (Achilles), heart block.","Uveíte, aortite, entesite."],["ebbo1315k","What is the Schober test?","Measures lumbar flexion; reduced in ankylosing spondylitis.","Mede a flexão lombar."],["1jns8q63y","Treatment of ankylosing spondylitis?","NSAIDs, exercise, anti-TNF or anti-IL-17 agents.","AINE e anti-TNF."],["w64d2wdc2","What is psoriatic arthritis?","Arthritis in psoriasis: DIP involvement, dactylitis (sausage digits), pencil-in-cup deformity, nail pitting, asymmetric oligoarthritis or symmetric.","Dedos em salsicha e unhas com depressões."],["1cw6jaamb","What is IBD-associated arthritis?","Arthritis with Crohn disease or UC; peripheral arthritis parallels bowel activity; axial disease independent.","Artrite acompanha a DII."],["hd435r14g","What is systemic lupus erythematosus?","Autoimmune disease with immune complex deposition (type III) and autoantibodies; mostly women of reproductive age (more severe in Black and Hispanic women).","Doença autoimune multissistêmica."],["durzy9sfa","Clinical features of SLE?","Malar rash, discoid rash, photosensitivity, oral ulcers, arthritis (nonerosive), serositis, nephritis, neurologic disorders, hematologic disorders, immunologic and ANA positivity.","Rash malar, artrite, serosite, nefrite."],["1xr7ge4x4","Mnemonic for SLE features?","RASH OR PAIN: Rash, Arthritis, Serositis, Hematologic disorders, Oral/nasopharyngeal ulcers, Renal disease, Photosensitivity, ANA, Immunologic, Neurologic.","Mnemônico RASH OR PAIN."],["hdsii8r36","What lab findings occur in active SLE?","Decreased C3 and C4 (complement consumption), increased anti-dsDNA.","Complemento baixo e anti-DNA alto."],["1pd7k4o19","What are the common causes of death in SLE?","Infections, renal disease (lupus nephritis), cardiovascular disease (accelerated atherosclerosis).","Infecções, nefrite e doença cardiovascular."],["9q8xkb1uv","What is the most common and severe lupus nephritis?","Diffuse proliferative glomerulonephritis (class IV): wire-loop lesions, subendothelial deposits.","Classe IV com alças de arame."],["1n774icav","What drugs cause drug-induced lupus?","Hydralazine, procainamide, isoniazid, minocycline, TNF inhibitors, quinidine, methyldopa (antihistone antibodies).","Hidralazina, procainamida, isoniazida."],["i6e6xf1q3","How does drug-induced lupus differ from SLE?","Rarely renal or CNS involvement; antihistone antibodies; resolves after stopping the drug.","Raramente rim ou SNC."],["1p385oty9","Treatment of SLE?","Hydroxychloroquine (all patients), NSAIDs, glucocorticoids, immunosuppressants (mycophenolate, cyclophosphamide for nephritis), belimumab, anifrolumab.","Hidroxicloroquina para todos."],["elt8lz1y9","What is neonatal lupus?","Anti-Ro/SSA antibodies from mother cause congenital heart block and rash in the newborn.","Bloqueio cardíaco congênito."],["1ifvxq31a","What is antiphospholipid syndrome in SLE?","Arterial and venous thrombosis, recurrent miscarriages, livedo reticularis; prolonged PTT and false-positive VDRL.","Trombose e abortos."],["7hm8ge1vf","What is Sjögren syndrome?","Autoimmune lymphocytic destruction of exocrine glands (lacrimal, salivary): dry eyes, dry mouth, parotid enlargement, dental caries; anti-Ro, anti-La.","Olho seco e boca seca."],["zdzkoi8g0","What are complications of Sjögren syndrome?","B-cell (MALT) lymphoma, renal tubular acidosis, interstitial lung disease, neonatal lupus.","Linfoma B."],["1i80e1if8","What test assesses tear production in Sjögren syndrome?","Schirmer test.","Teste de Schirmer."],["1an8kcy16","What is systemic sclerosis (scleroderma)?","Autoimmune excess collagen deposition and fibrosis of skin and organs with vascular damage.","Fibrose de pele e órgãos."],["1tb1isfdx","What is diffuse scleroderma?","Widespread skin involvement, rapid progression, early visceral involvement (lungs, kidneys: scleroderma renal crisis); anti-Scl-70 and anti-RNA polymerase III.","Forma difusa com crise renal."],["1xsb36f1k","What is limited scleroderma (CREST)?","Calcinosis, Raynaud phenomenon, Esophageal dysmotility, Sclerodactyly, Telangiectasia; anticentromere; later pulmonary hypertension.","CREST; anticentrômero."],["h3vinoxyl","What is scleroderma renal crisis?","Abrupt hypertension and acute renal failure, often triggered by steroids; treated with ACE inhibitors.","Hipertensão e falência renal; IECA."],["1rpra7i1j","What is the leading cause of death in systemic sclerosis?","Pulmonary disease (interstitial lung disease and pulmonary hypertension).","Doença pulmonar."],["jd4y42rd6","What is mixed connective tissue disease?","Features of SLE, systemic sclerosis, and polymyositis; anti-U1 RNP.","Sobreposição de doenças; anti-U1 RNP."],["116ganjjt","What is polymyositis?","Progressive symmetric proximal muscle weakness, CD8+ T-cell endomysial inflammation; increased CK; anti-Jo-1.","Fraqueza proximal com CPK alta."],["zn6jxd1ty","What is dermatomyositis?","Proximal muscle weakness with skin findings (heliotrope rash, Gottron papules, shawl and V-sign, mechanic's hands); CD4+ perimysial inflammation; associated with malignancy.","Fraqueza com heliótropo e pápulas de Gottron."],["t10s98xjj","What malignancies are associated with dermatomyositis?","Ovarian, lung, GI, pancreatic, non-Hodgkin lymphoma (screen for cancer).","Ovário, pulmão, trato digestivo."],["gudn3mybp","Treatment of polymyositis and dermatomyositis?","Glucocorticoids, then methotrexate or azathioprine, IVIG.","Corticoide e imunossupressores."],["13mlz771m","What is inclusion body myositis?","Most common myopathy over age 50: asymmetric weakness of finger flexors and quadriceps, rimmed vacuoles; poor response to steroids.","Miopatia do idoso que não responde a corticoide."],["1vazhzd1l","What is statin-induced myopathy?","Myalgias with or without elevated CK; rare necrotizing autoimmune myopathy with anti-HMGCR antibodies.","Dor muscular por estatina."],["1kckzcban","What is myasthenia gravis?","Autoantibodies against postsynaptic ACh receptors: ptosis, diplopia, weakness worse with use, improves with rest.","Fraqueza que piora com uso."],["1rna96086","What tests diagnose myasthenia gravis?","Anti-AChR antibodies, repetitive nerve stimulation (decremental response), edrophonium (historical), ice pack test for ptosis, CT for thymoma.","Anticorpos anti-AChR e teste do gelo."],["gsves6bds","Treatment of myasthenia gravis?","Pyridostigmine (AChE inhibitor), immunosuppression, thymectomy, IVIG or plasmapheresis for crisis.","Piridostigmina e timectomia."],["bypb2xmtg","What is Lambert-Eaton myasthenic syndrome?","Antibodies against presynaptic voltage-gated Ca2+ channels: proximal weakness improving with repeated use, autonomic symptoms, hyporeflexia; associated with small cell lung cancer.","Melhora com uso; câncer de pequenas células."],["zj1pdi1xt","What is the difference between myasthenia and Lambert-Eaton on repetitive stimulation?","Myasthenia: decremental response. Lambert-Eaton: incremental response.","Miastenia decresce; Lambert-Eaton aumenta."],["1gv2m191f","What is sarcoidosis?","Systemic noncaseating granulomatous disease, often in Black women: bilateral hilar adenopathy, reticular opacities, erythema nodosum, uveitis, hypercalcemia (calcitriol), elevated ACE.","Granulomas não caseosos; adenopatia hilar."],["10iv3tpt5","What is Löfgren syndrome?","Acute sarcoidosis: erythema nodosum, bilateral hilar lymphadenopathy, migratory polyarthralgia, fever; good prognosis.","Forma aguda de bom prognóstico."],["13j6a5sqn","Treatment of sarcoidosis?","Glucocorticoids if symptomatic; methotrexate or anti-TNF for refractory cases.","Corticoide."],["ubbarc1t2","What is a macule?","Flat lesion <1 cm with color change (freckle).","Mancha plana menor que 1 cm."],["16d1aw594","What is a patch?","Flat lesion >1 cm (vitiligo, large birthmark).","Mancha plana maior que 1 cm."],["4nnxke1of","What is a papule vs a plaque?","Papule: elevated solid lesion <1 cm (mole). Plaque: elevated solid lesion >1 cm (psoriasis).","Pápula pequena; placa grande."],["1gzbipmc4","What is a vesicle vs a bulla?","Vesicle: small fluid-filled blister <1 cm. Bulla: >1 cm.","Vesícula pequena; bolha grande."],["1m5tj2tl9","What is a pustule?","Vesicle filled with pus (pustular psoriasis, acne).","Vesícula com pus."],["1754l307b","What is a wheal?","Transient smooth papule or plaque from dermal edema (hives).","Urticária."],["f43y8r9k3","What is hyperkeratosis vs parakeratosis?","Hyperkeratosis: thickened stratum corneum. Parakeratosis: retained nuclei in stratum corneum (psoriasis).","Camada córnea espessa versus com núcleos."],["1fscnts40","What is spongiosis?","Epidermal accumulation of edematous fluid in intercellular spaces (eczematous dermatitis).","Edema entre as células; eczema."],["1t0uga0zn","What is acantholysis?","Separation of epidermal cells (pemphigus vulgaris).","Separação das células; pênfigo."],["1gu33zxpq","What is acanthosis?","Epidermal hyperplasia (thickened stratum spinosum), e.g., acanthosis nigricans, psoriasis.","Espessamento da camada espinhosa."],["nu7gd111m","What is psoriasis?","Papules and plaques with silvery scale on extensor surfaces and scalp; nail pitting; Auspitz sign (pinpoint bleeding); Munro microabscesses; Koebner phenomenon.","Placas com escamas prateadas."],["ynxj6wf42","Treatment of psoriasis?","Topical steroids, vitamin D analogs (calcipotriol), phototherapy, methotrexate, biologics (anti-TNF, anti-IL-17, anti-IL-23).","Corticoide tópico e biológicos."],["68llo2r3d","What is atopic dermatitis (eczema)?","Pruritic erythematous oozing rash with scaling in flexural surfaces (adults) or face (infants); associated with asthma and allergic rhinitis; filaggrin mutations.","Eczema pruriginoso em dobras."],["1kfi5j19t","What is allergic contact dermatitis?","Type IV hypersensitivity to nickel, poison ivy, neomycin: pruritic rash at contact site.","Reação tardia ao contato."],["jxibne1df","What is seborrheic dermatitis?","Erythematous greasy scaly patches on scalp, face, chest (cradle cap); associated with Malassezia and Parkinson disease.","Descamação oleosa; caspa."],["j9liex1f9","What is seborrheic keratosis?","Benign flat, waxy, stuck-on lesions in elderly; horn cysts; Leser-Trélat sign if sudden appearance.","Lesões verrucosas coladas na pele."],["16lqbqx1g","What is acanthosis nigricans?","Velvety hyperpigmented plaques in axilla and neck; associated with insulin resistance and visceral malignancy (gastric).","Placas aveludadas escuras no pescoço."],["1uhykampx","What is actinic keratosis?","Premalignant scaly erythematous lesions on sun-exposed areas; risk of squamous cell carcinoma.","Lesão pré-maligna por sol."],["3mjzsq1lr","What is lichen planus?","Pruritic, purple, polygonal, planar papules and plaques (6 Ps) with Wickham striae; sawtooth infiltrate of lymphocytes; associated with hepatitis C.","Pápulas roxas pruriginosas; hepatite C."],["6qobr16xs","What is pityriasis rosea?","Herald patch followed by Christmas tree distribution of scaly patches; self-resolving (HHV-6/7).","Placa mãe e lesões em árvore de Natal."],["hfr137ds3","What is pemphigus vulgaris?","IgG antibodies against desmoglein 1 and 3: flaccid intraepidermal bullae, oral mucosa involved, positive Nikolsky sign, net-like immunofluorescence.","Bolhas flácidas e mucosa oral; Nikolsky positivo."],["tz67lkm82","What is bullous pemphigoid?","IgG against hemidesmosomes (BP180, BP230): tense subepidermal bullae, mucosa spared, Nikolsky negative, linear immunofluorescence along basement membrane; elderly.","Bolhas tensas em idosos."],["q7qp0d1yq","What is dermatitis herpetiformis?","Pruritic papules and vesicles on extensor surfaces; IgA deposits at the tips of dermal papillae; associated with celiac disease; treated with dapsone and gluten-free diet.","Vesículas pruriginosas; doença celíaca."],["we0mzvsbl","What is erythema multiforme?","Target lesions (central dusky area); associated with HSV (most common), Mycoplasma, drugs.","Lesões em alvo; herpes."],["1300hhr1r","What is Stevens-Johnson syndrome?","Severe mucocutaneous reaction with epidermal detachment <10% BSA, fever, mucosal involvement; drugs (sulfa, anticonvulsants, allopurinol, NSAIDs).","Descolamento <10% com mucosas."],["mp4qpxo5a","What is toxic epidermal necrolysis?","Epidermal detachment >30% BSA; same causes as SJS, higher mortality.","Descolamento >30%."],["1q43wlsr0","What is erythema nodosum?","Painful raised inflammatory lesions of subcutaneous fat (panniculitis) on anterior shins; associated with sarcoidosis, IBD, strep infection, TB, coccidioidomycosis, pregnancy.","Nódulos dolorosos nas canelas."],["1u6gomgvk","What is urticaria?","Pruritic wheals from mast cell degranulation; acute (allergic) or chronic.","Urticária por mastócitos."],["cv1zut3lm","What is vitiligo?","Autoimmune loss of melanocytes causing depigmented patches; associated with other autoimmune diseases.","Perda de melanócitos."],["rrhqpg1l6","What is albinism's defect?","Normal melanocyte number with decreased melanin production (tyrosinase deficiency) or defective tyrosine transport; increased skin cancer risk.","Melanócitos normais sem melanina."],["1cyuka8ne","What is melasma?","Hyperpigmentation of the face associated with pregnancy or OCPs.","Manchas faciais na gravidez."],["10nknty1e","What is basal cell carcinoma?","Most common skin cancer; sun-exposed areas (upper lip); pearly papules with rolled borders and telangiectasias; palisading nuclei; locally invasive, rarely metastasizes.","Pápula perolada com telangiectasias."],["1c8uysm1s","What is squamous cell carcinoma of the skin?","Second most common skin cancer; sun exposure, immunosuppression, arsenic, chronic wounds (Marjolin ulcer); ulcerative lesions on lower lip, hands; keratin pearls.","Lesão ulcerada; pérolas de queratina."],["1ba8nwest","What is keratoacanthoma?","Rapidly growing crater-shaped nodule with central keratin plug; variant of SCC that may regress.","Nódulo em cratera de crescimento rápido."],["1htgq4i1q","What is melanoma?","Malignant melanocyte tumor; S-100 and HMB-45 positive; risk from sun exposure, dysplastic nevi; depth (Breslow) is most important prognostic factor.","Profundidade de Breslow define prognóstico."],["10crqrw1f","What are the ABCDEs of melanoma?","Asymmetry, Border irregularity, Color variation, Diameter >6 mm, Evolution.","Assimetria, bordas, cor, diâmetro, evolução."],["1v49h8k1t","Which mutation is common in melanoma and is targetable?","BRAF V600E (vemurafenib, dabrafenib).","BRAF V600E."],["1csgfc71s","What is the most aggressive subtype of melanoma?","Nodular melanoma (vertical growth).","Melanoma nodular."],["1pytk6k14","What is acral lentiginous melanoma?","Melanoma on palms, soles, nail beds; most common in dark-skinned people; not UV-related.","Palmas, plantas e unhas."],["19w65721i","What is impetigo?","Superficial skin infection (S. aureus or S. pyogenes) with honey-crusted lesions; bullous form from S. aureus.","Crostas cor de mel."],["1ksy9hkg6","What is cellulitis vs erysipelas?","Cellulitis: deeper dermis and subcutaneous tissue, poorly demarcated. Erysipelas: upper dermis, well-demarcated raised border (S. pyogenes).","Celulite profunda; erisipela bem delimitada."],["1k5c5dt18","What is necrotizing fasciitis?","Deep infection along fascial planes with crepitus and pain out of proportion; surgical emergency.","Infecção profunda; emergência cirúrgica."],["1y44an1pw","What is staphylococcal scalded skin vs TEN in terms of skin layer?","SSSS: split in stratum granulosum (no mucosa). TEN: full epidermal necrosis at dermal-epidermal junction (mucosa involved).","SSSS superficial; NET profunda."],["p5yio55xp","What are verrucae (warts)?","HPV-induced soft, tan, cauliflower papules; koilocytes.","Verrugas por HPV."],["8llyst11s","What is a hemangioma vs a port-wine stain?","Hemangioma: grows and then regresses in infants. Port-wine stain: does not regress, associated with Sturge-Weber.","Hemangioma regride; mancha vinho do Porto não."],["m5bkv6xqc","What is rosacea?","Facial erythema, flushing, telangiectasias, papules and pustules (no comedones); rhinophyma in late stage.","Vermelhidão facial sem comedões."],["1gcntro11","What is acne vulgaris's pathogenesis?","Increased sebum (androgens), abnormal follicular keratinization, Cutibacterium acnes, inflammation.","Sebo, queratinização e bactéria."],["1vks4am1m","What is hidradenitis suppurativa?","Chronic inflammatory disease of apocrine areas (axilla, groin) with painful nodules, abscesses, sinus tracts.","Nódulos dolorosos em axilas e virilha."],["1f7aeleer","What is xanthoma?","Lipid-laden histiocytes in skin (xanthelasma on eyelids) associated with hyperlipidemia.","Depósitos de lipídios na pele."],["6u52qb3f4","What is a dermatofibroma?","Benign firm nodule on legs that dimples when pinched (fibroblast proliferation).","Nódulo firme que afunda ao pinçar."],["17mkz5pcg","What is a lipoma?","Soft, mobile, benign subcutaneous fat tumor.","Tumor benigno de gordura."],["1c6oatt1v","What is a liposarcoma?","Malignant adipose tumor, often retroperitoneal; MDM2 amplification.","Tumor maligno de gordura."],["1ri11lv17","What is rhabdomyosarcoma?","Most common soft tissue sarcoma of childhood (head and neck, GU); desmin and myogenin positive.","Sarcoma mais comum na infância."],["dv59kj1se","What is a leiomyoma?","Benign smooth muscle tumor (uterus most common).","Mioma."],["u9m32flwx","What is a desmoid tumor?","Locally aggressive fibroblastic tumor; associated with Gardner syndrome (FAP).","Tumor fibroso agressivo."],["9y040ipb6","What is the Koebner phenomenon?","Skin lesions appearing at sites of trauma (psoriasis, lichen planus, vitiligo).","Lesões em locais de trauma."],["1in6hwu11","What is the Nikolsky sign?","Separation of epidermis with gentle rubbing (pemphigus vulgaris, SSSS, TEN).","Pele descola ao friccionar."],["12oxjc1lq","What is burn classification by depth?","Superficial (epidermis, painful, erythema), partial thickness (blisters, painful), full thickness (through dermis, painless, white/leathery), deeper (fat, muscle, bone).","Classificação das queimaduras."],["1yohhn81s","What is the rule of nines in burns?","Estimate of body surface area: head 9%, each arm 9%, each leg 18%, anterior trunk 18%, posterior trunk 18%, perineum 1%.","Regra dos nove."],["16mkb6a1y","What is the Parkland formula?","IV fluids in first 24 hours = 4 mL x weight (kg) x %TBSA burned; half in first 8 hours.","Reposição em queimados."],["96mcb21bo","What are complications of burns?","Hypovolemic shock, infection (Pseudomonas), Curling ulcers, hypothermia, compartment syndrome, contractures.","Choque, infecção, úlcera de Curling."],["2sneyo1gw","What is the cause of pressure ulcers?","Prolonged pressure over bony prominences (sacrum, heels) in immobile patients.","Pressão prolongada em proeminências ósseas."],["ip5myp1ew","What is keloid formation?","Excess type III collagen beyond wound borders; more common in African Americans, earlobes.","Cicatriz que ultrapassa a ferida."],["se5cz9alp","How does a hypertrophic scar differ from a keloid?","Hypertrophic scar stays within the wound borders and may regress; keloid extends beyond and rarely regresses.","Hipertrófica fica nos limites."],["gqqd651og","What are the phases of wound healing?","Inflammatory (0-3 days), proliferative (3 days-weeks: granulation tissue, type III collagen), remodeling (weeks-months: type I collagen replaces type III).","Inflamação, proliferação, remodelação."],["4jfn8qyp5","What impairs wound healing?","Infection, diabetes, ischemia, malnutrition, vitamin C and zinc deficiency, steroids, smoking.","Infecção, diabetes, desnutrição, corticoide."],["1ajd42m1t","What is the role of myofibroblasts in wound healing?","Wound contraction.","Contração da ferida."],["17fd1k6mr","What is dermatomyositis's characteristic nailfold finding?","Dilated capillary loops and periungual erythema.","Capilares dilatados na cutícula."],["211if01ng","What is livedo reticularis associated with?","Antiphospholipid syndrome, SLE, cholesterol emboli, polyarteritis nodosa.","Antifosfolípide e embolia de colesterol."],["1voy9up6r","What is pyoderma gangrenosum?","Painful ulcer with violaceous undermined borders; associated with IBD, rheumatoid arthritis, hematologic malignancy.","Úlcera dolorosa de bordas violáceas."],["z7dhu3ulh","What is Gottron's papules?","Violaceous papules over the knuckles in dermatomyositis.","Pápulas nos nós dos dedos."],["2tpdls1o0","What is the heliotrope rash?","Violaceous periorbital edema and rash in dermatomyositis.","Edema violáceo nas pálpebras."],["1oiazam1y","What is the treatment of chronic urticaria?","Second-generation H1 antihistamines (higher doses), omalizumab if refractory.","Anti-histamínicos e omalizumabe."],["wljejhg80","What is mycosis fungoides's skin finding?","Scaly patches and plaques progressing to tumors (cutaneous T-cell lymphoma).","Placas descamativas; linfoma T."],["1dyz79igi","What is scabies?","Sarcoptes scabiei: intensely pruritic papules and burrows in web spaces and wrists, worse at night; treated with permethrin.","Coceira noturna nos espaços entre dedos."],["66irzy1kd","What is the difference between seborrheic keratosis and melanoma?","Seborrheic keratosis is stuck-on, waxy, with horn cysts; melanoma shows ABCDE changes.","Ceratose seborreica é benigna e colada."],["125ss8wi6","What is the treatment for basal cell carcinoma?","Surgical excision (Mohs surgery for face).","Excisão; cirurgia de Mohs."],["thxt7uma5","What is the role of sunscreen and sun protection?","Reduces risk of squamous cell carcinoma and melanoma.","Reduz câncer de pele."],["17jnvm51q","What is the most important risk factor for melanoma?","Intermittent intense sun exposure (sunburns), especially in childhood, and fair skin.","Queimaduras solares na infância."],["1ulfrpn1w","What is the gene associated with familial melanoma?","CDKN2A (p16).","CDKN2A."],["5vcw4q14x","What is the lymph node evaluation in melanoma?","Sentinel lymph node biopsy for lesions >0.8 mm thick.","Biópsia do linfonodo sentinela."],["1pnz4l0as","What causes hyperpigmentation in Addison disease?","Increased ACTH/POMC stimulating melanocytes (MSH effect).","ACTH alto estimula melanócitos."],["bfe2ij1f3","What is ochronosis?","Blue-black pigmentation of connective tissue in alkaptonuria.","Pigmentação escura na alcaptonúria."],["1s547jg15","What is the cause of argyria?","Silver deposition causing blue-gray skin.","Depósito de prata."],["1aqc41iv9","What is the cause of blue-gray skin from a cardiac drug?","Amiodarone.","Amiodarona."],["1pj3eme95","What is the cause of yellow skin sparing the sclerae?","Carotenemia.","Carotenemia."],["1t5ulwh46","What is the cause of bronze skin with diabetes?","Hemochromatosis.","Hemocromatose."],["1kbkaag9i","What is the treatment for actinic keratosis?","Cryotherapy, topical 5-FU, imiquimod, photodynamic therapy.","Crioterapia ou 5-FU tópico."],["ladaqd190","What is erythrasma's appearance under Wood lamp?","Coral-red fluorescence (Corynebacterium minutissimum).","Fluorescência vermelho-coral."],["1gn5hp61m","What is tinea versicolor's appearance under Wood lamp?","Yellow-green fluorescence (Malassezia).","Amarelo-esverdeado."],["10vivym1f","What is the most common cause of folliculitis?","Staphylococcus aureus (hot tub: Pseudomonas).","S. aureus."],["11tt59g1f","What is the classic presentation of SLE in a young woman?","Fatigue, fever, malar rash sparing nasolabial folds, arthralgias, positive ANA.","Rash malar poupando sulcos nasolabiais."],["1a4r1v11a","What is the most sensitive test for SLE?","ANA (negative ANA makes SLE unlikely).","FAN."],["1iofgrs1h","What is Raynaud phenomenon's association with systemic sclerosis?","Present in nearly all patients, often the first symptom.","Presente em quase todos."],["2bmwyk9ed","What is the esophageal finding in systemic sclerosis?","Decreased LES tone and distal esophageal dysmotility (GERD, dysphagia).","Refluxo e dismotilidade."],["191zwee10","What is morphea?","Localized scleroderma limited to the skin without internal organ involvement.","Esclerodermia localizada."],["4lpi2d1w5","What is eosinophilic fasciitis?","Painful swelling and induration of extremities with peau d'orange, eosinophilia, sparing hands and face; responds to steroids.","Endurecimento com eosinofilia."],["1ekdymado","What is relapsing polychondritis?","Recurrent inflammation of cartilage (ears, nose, trachea) sparing the earlobe.","Inflamação da cartilagem da orelha."],["1jiruqhez","What is IgG4-related disease?","Fibroinflammatory condition with IgG4+ plasma cells affecting pancreas, salivary glands, retroperitoneum; responds to steroids.","Fibrose com plasmócitos IgG4."],["akdfmuu24","What is Behçet disease's diagnostic triad?","Recurrent oral ulcers, genital ulcers, uveitis (plus pathergy test).","Aftas orais, úlceras genitais e uveíte."]]},{"name":"Pharmacology","cards":[["17jkn2u11","Mechanism of aspirin?","Irreversibly inhibits COX-1 and COX-2 by acetylation, decreasing thromboxane A2 and prostaglandins.","Inibe COX de forma irreversível."],["1nfk1fc1m","Dose-dependent effects of aspirin?","Low dose: antiplatelet. Intermediate: antipyretic and analgesic. High: anti-inflammatory.","Dose baixa antiagregante; alta anti-inflamatória."],["1ylvm2j1s","Adverse effects of aspirin?","Gastric ulceration, tinnitus (CN VIII), Reye syndrome in children, bleeding, aspirin-exacerbated respiratory disease.","Úlcera, zumbido, Reye."],["o8kw7v1jl","What happens in aspirin (salicylate) overdose?","Early respiratory alkalosis (stimulates respiratory center), then mixed with anion gap metabolic acidosis; tinnitus, hyperthermia (uncoupling).","Alcalose respiratória e depois acidose metabólica."],["149a9it1k","Treatment of salicylate overdose?","Sodium bicarbonate (alkalinizes urine to enhance excretion), dialysis if severe.","Bicarbonato e diálise se grave."],["1lsbmc54l","What is aspirin-exacerbated respiratory disease?","Triad of asthma, nasal polyps, aspirin sensitivity: COX inhibition shunts arachidonic acid to leukotrienes.","Asma, pólipos e sensibilidade à aspirina."],["1q55klg1b","Mechanism of NSAIDs (ibuprofen, naproxen, indomethacin, ketorolac, diclofenac, meloxicam)?","Reversibly inhibit COX-1 and COX-2, blocking prostaglandin synthesis.","Inibem COX de forma reversível."],["r57x351u2","Uses of NSAIDs?","Antipyretic, analgesic, anti-inflammatory; indomethacin closes PDA and treats gout.","Febre, dor e inflamação."],["1boelif11","Adverse effects of NSAIDs?","Interstitial nephritis, gastric ulcer, renal ischemia (afferent arteriole constriction), aplastic anemia, increased cardiovascular risk.","Úlcera, nefrite e isquemia renal."],["10d0is61h","Why are NSAIDs harmful in renal insufficiency or heart failure?","Prostaglandins dilate afferent arterioles; inhibition reduces GFR and causes sodium retention.","Reduzem a filtração."],["1a5kq5h3w","Mechanism of COX-2 inhibitors (celecoxib)?","Reversibly inhibit COX-2 selectively (inflammation and pain), sparing gastric mucosa and platelets.","Poupam estômago e plaquetas."],["aam8gl102","Adverse effects of celecoxib?","Increased risk of thrombosis (MI, stroke) because thromboxane is unopposed; sulfa allergy.","Risco de trombose."],["1a837po15","Mechanism of acetaminophen?","Reversibly inhibits COX mostly in CNS; inactivated peripherally.","Inibe COX no SNC."],["16bmhhjib","Uses of acetaminophen?","Antipyretic and analgesic, not anti-inflammatory; used instead of aspirin in children with viral infections.","Febre e dor, sem ação anti-inflamatória."],["onxx2e9sk","Mechanism of acetaminophen hepatotoxicity?","Overdose depletes glutathione, NAPQI accumulates and causes centrilobular hepatic necrosis.","NAPQI causa necrose centrolobular."],["9l0qou12b","Antidote for acetaminophen overdose?","N-acetylcysteine (regenerates glutathione).","N-acetilcisteína."],["17tvavp2p","Mechanism and uses of bisphosphonates?","Pyrophosphate analogs that bind hydroxyapatite and inhibit osteoclast activity; osteoporosis, hypercalcemia, Paget disease, metastatic bone disease, osteogenesis imperfecta.","Inibem osteoclastos."],["1irwltz1d","How should oral bisphosphonates be taken?","With a full glass of water, empty stomach, upright for 30 minutes.","Em jejum, com água, sentado."],["11atyubuc","Adverse effects of bisphosphonates?","Esophagitis, osteonecrosis of the jaw, atypical femoral stress fractures.","Esofagite, osteonecrose da mandíbula."],["1gk5a5014","Mechanism and use of teriparatide?","Recombinant PTH analog given intermittently, increasing osteoblastic activity; severe osteoporosis.","PTH intermitente forma osso."],["1dbgfduza","Mechanism and use of romosozumab?","Monoclonal antibody against sclerostin, increasing bone formation and decreasing resorption; risk of cardiovascular events.","Anti-esclerostina."],["efuque1br","Mechanism and use of denosumab in osteoporosis?","Anti-RANKL monoclonal antibody, inhibiting osteoclast formation; given every 6 months.","Anti-RANKL semestral."],["16ofa391r","Mechanism of allopurinol?","Inhibits xanthine oxidase, decreasing conversion of xanthine to uric acid.","Inibe a xantina oxidase."],["67126dxfa","Uses of allopurinol?","Chronic gout prevention, tumor lysis syndrome prevention, uric acid stones.","Gota crônica e lise tumoral."],["c7qooo1e0","Adverse effects of allopurinol?","Hypersensitivity (SJS, DRESS; HLA-B*58:01 risk), increases azathioprine and 6-MP toxicity.","Reação grave; interação com azatioprina."],["258qbo1k1","Mechanism and adverse effects of febuxostat?","Nonpurine xanthine oxidase inhibitor; may increase cardiovascular death risk, liver enzyme elevation.","Inibe xantina oxidase; risco cardiovascular."],["12xsi871j","Mechanism of probenecid?","Inhibits reabsorption of uric acid in the PCT (also inhibits secretion of penicillin).","Aumenta excreção de ácido úrico."],["1lqysih1g","Adverse effect of probenecid?","Uric acid kidney stones (avoid in overproducers or stone history).","Cálculos de ácido úrico."],["jc2bp4ca8","Mechanism and use of pegloticase?","Recombinant uricase converting uric acid to allantoin; refractory chronic gout; contraindicated in G6PD deficiency.","Uricase; não usar na G6PD."],["3hsrtvzxf","Mechanism and use of colchicine?","Binds tubulin and prevents microtubule polymerization, impairing neutrophil chemotaxis and degranulation; acute gout, prophylaxis, pericarditis, familial Mediterranean fever.","Inibe microtúbulos e neutrófilos."],["166sfra1t","Adverse effects of colchicine?","GI (diarrhea), myopathy and neuropathy (especially with renal impairment or CYP3A4 inhibitors).","Diarreia e miopatia."],["1h78zntfo","Which drugs treat acute gout?","NSAIDs, glucocorticoids, colchicine (avoid salicylates).","AINE, corticoide ou colchicina."],["u68cq2qt8","Why should salicylates be avoided in gout?","Low doses decrease uric acid excretion.","Doses baixas retêm ácido úrico."],["gk9ghwkiw","Mechanism and use of methotrexate in RA?","DHFR inhibition and adenosine release with anti-inflammatory effects; first-line DMARD.","Primeira escolha na artrite reumatoide."],["1a0ceng1m","What supplement reduces methotrexate adverse effects in RA?","Folic acid.","Ácido fólico."],["1dk9u6210","Mechanism and use of hydroxychloroquine?","Antimalarial with immunomodulatory effects (TLR inhibition); SLE, mild RA, Sjögren.","Lúpus e artrite leve."],["sarmx4ngk","Adverse effect of hydroxychloroquine requiring screening?","Retinopathy (annual eye exams after 5 years).","Retinopatia."],["1i0kl5j11","Mechanism and use of sulfasalazine in arthritis?","Anti-inflammatory 5-ASA and sulfapyridine; RA, ankylosing spondylitis (peripheral), UC.","Artrite e RCU."],["35dz0ym1m","Mechanism and use of leflunomide?","Inhibits dihydroorotate dehydrogenase (pyrimidine synthesis), reducing T-cell proliferation; RA, psoriatic arthritis.","Inibe síntese de pirimidinas."],["rwtbivanl","Adverse effects of leflunomide?","Hepatotoxicity, teratogenicity, diarrhea, hypertension.","Hepatotóxico e teratogênico."],["7tkk2jv76","Which biologics are used in RA?","TNF inhibitors (etanercept, infliximab, adalimumab, golimumab, certolizumab), rituximab, abatacept, tocilizumab, anakinra; JAK inhibitors (tofacitinib, baricitinib, upadacitinib).","Anti-TNF, rituximabe, abatacepte, tocilizumabe, inibidores de JAK."],["xyj3gq1zq","What is the role of glucocorticoids in rheumatology?","Rapid control of inflammation (bridge therapy), giant cell arteritis, polymyalgia rheumatica, SLE flares, vasculitis.","Controle rápido da inflamação."],["1ygrzvpxd","Mechanism and use of cyclophosphamide in rheumatology?","Alkylating agent for severe lupus nephritis and ANCA vasculitis.","Nefrite lúpica e vasculites graves."],["1av1zbqzq","Mechanism and use of mycophenolate in lupus nephritis?","IMP dehydrogenase inhibitor reducing lymphocyte proliferation; induction and maintenance therapy.","Tratamento da nefrite lúpica."],["1ruzil05d","Mechanism and use of belimumab?","Anti-BAFF (B-cell activating factor) monoclonal antibody for SLE.","Anti-BAFF no lúpus."],["1nm6fxm1q","Mechanism and use of anifrolumab?","Type I interferon receptor antagonist for SLE.","Bloqueia interferon tipo I no lúpus."],["qtjoo1hmz","Mechanism and use of apremilast?","PDE4 inhibitor for psoriasis and psoriatic arthritis, Behçet oral ulcers.","Inibidor de PDE4 na psoríase."],["lvx7ni1wi","Mechanism and use of IL-17 inhibitors in rheumatology?","Secukinumab, ixekizumab: psoriasis, psoriatic arthritis, ankylosing spondylitis; may worsen IBD.","Anti-IL-17; pode piorar DII."],["1to7lem1f","Mechanism and use of IL-23 inhibitors?","Guselkumab, risankizumab, tildrakizumab: psoriasis and psoriatic arthritis, Crohn disease.","Anti-IL-23."],["px1vls1jv","Mechanism and use of dantrolene?","Prevents release of Ca2+ from sarcoplasmic reticulum (ryanodine receptor); malignant hyperthermia, neuroleptic malignant syndrome.","Bloqueia rianodina; hipertermia maligna."],["1lup44uji","Mechanism and use of baclofen?","GABA-B agonist at the spinal cord; muscle spasticity (MS, spinal cord injury).","Agonista GABA-B; espasticidade."],["1kctqyw8d","Mechanism and use of cyclobenzaprine?","Centrally acting skeletal muscle relaxant structurally related to TCAs; muscle spasm; anticholinergic side effects.","Relaxante muscular parecido com tricíclico."],["1jricrr5h","Mechanism and use of tizanidine?","Central alpha-2 agonist; spasticity; hypotension and sedation.","Agonista alfa-2; espasticidade."],["xkh1zr1g4","Mechanism and use of botulinum toxin therapeutically?","Blocks ACh release; dystonia, spasticity, migraine prophylaxis, hyperhidrosis, cosmetic.","Distonia, enxaqueca, cosmético."],["1p4rywm1h","Mechanism of succinylcholine?","Depolarizing neuromuscular blocker binding nicotinic ACh receptors (phase I: depolarization; phase II: desensitization).","Bloqueador despolarizante."],["b5bp3v8s4","Adverse effects of succinylcholine?","Hyperkalemia (burns, crush injuries, denervation), malignant hyperthermia, bradycardia.","Hipercalemia e hipertermia maligna."],["1aw89ax2u","Mechanism of nondepolarizing neuromuscular blockers?","Competitive antagonists at nicotinic ACh receptors (rocuronium, vecuronium, cisatracurium).","Antagonistas competitivos."],["1q89thq68","Reversal of nondepolarizing neuromuscular blockade?","Neostigmine (with glycopyrrolate) or sugammadex (encapsulates rocuronium/vecuronium).","Neostigmina ou sugamadex."],["1p22xjb2l","Why is cisatracurium used in hepatic or renal failure?","Undergoes spontaneous Hofmann elimination.","Degradação espontânea."],["boqunn1c7","Topical treatments for acne?","Retinoids, benzoyl peroxide, topical antibiotics (clindamycin), azelaic acid.","Retinoides e peróxido de benzoíla."],["1ag82766m","Systemic treatments for severe acne?","Oral antibiotics (doxycycline), hormonal therapy (OCPs, spironolactone), isotretinoin.","Doxiciclina e isotretinoína."],["ie59k8c1e","Adverse effects of isotretinoin?","Teratogenicity (iPLEDGE program), dry skin and lips, hepatotoxicity, hyperlipidemia, depression, pseudotumor cerebri.","Teratogênico; pele seca."],["1qr2wmkbj","Mechanism and use of minoxidil topically?","Hair regrowth in androgenetic alopecia (K+ channel opener).","Crescimento de cabelo."],["3l0cig3au","Mechanism and use of finasteride?","5-alpha-reductase inhibitor; BPH and androgenetic alopecia.","Inibe 5-alfa-redutase."],["19uy6es1e","Mechanism and use of topical calcineurin inhibitors?","Tacrolimus and pimecrolimus ointment; atopic dermatitis (steroid-sparing, face and folds).","Dermatite atópica sem corticoide."],["f40q69ggh","Mechanism and use of dupilumab in dermatology?","Anti-IL-4 receptor alpha; moderate-to-severe atopic dermatitis.","Dermatite atópica grave."],["1jnzdtysc","What are adverse effects of chronic topical steroids?","Skin atrophy, striae, telangiectasias, hypopigmentation, perioral dermatitis, HPA suppression with large areas.","Atrofia e estrias."],["1arstbu1j","Mechanism and use of calcipotriene?","Vitamin D analog that inhibits keratinocyte proliferation; psoriasis.","Análogo de vitamina D na psoríase."],["k8sydkyz6","Mechanism and use of methotrexate in psoriasis?","Antiproliferative and immunosuppressive; moderate-to-severe psoriasis and psoriatic arthritis.","Psoríase moderada a grave."],["1tuy7wmz0","Mechanism and use of permethrin?","Blocks Na+ channels in arthropod neurons causing paralysis; scabies and lice.","Escabiose e piolho."],["1sn2x15tc","Mechanism and use of 5-fluorouracil topical?","Antimetabolite for actinic keratosis and superficial basal cell carcinoma.","Ceratose actínica."],["mhm3hl1kg","Mechanism of capsaicin topical?","TRPV1 agonist depleting substance P from sensory nerves; neuropathic pain and arthritis.","Esgota substância P."],["s95idjxki","Mechanism of gabapentin and pregabalin?","Bind alpha-2-delta subunit of voltage-gated Ca2+ channels, reducing excitatory neurotransmitter release; neuropathic pain, fibromyalgia, postherpetic neuralgia.","Dor neuropática."],["srmqx0wom","Which antidepressants treat chronic pain and fibromyalgia?","SNRIs (duloxetine, milnacipran) and TCAs (amitriptyline).","Duloxetina e amitriptilina."],["1sbhuzw5x","Mechanism and use of tramadol?","Weak mu-opioid agonist that also inhibits serotonin and norepinephrine reuptake; chronic pain; lowers seizure threshold, serotonin syndrome.","Opioide fraco; reduz limiar convulsivo."],["1j4y1tdc6","Which drug prevents gout flares when starting allopurinol?","Low-dose colchicine (or NSAIDs).","Colchicina."],["1cbpq2f1m","Which drug is used for uric acid nephrolithiasis prevention?","Potassium citrate (alkalinizes urine) and allopurinol.","Citrato de potássio."],["1gd1yj1hn","Which drug is used for chronic gout in a patient with kidney stones?","Xanthine oxidase inhibitor (allopurinol), not probenecid.","Alopurinol."],["19rvtm21n","Which drugs are first-line for osteoarthritis pain?","Topical NSAIDs, oral NSAIDs, acetaminophen.","AINE tópico ou oral."],["6snf0s54k","Which drug class is first-line for ankylosing spondylitis?","NSAIDs.","AINEs."],["1kz6a1opc","Which drug is used in polymyalgia rheumatica?","Low-dose prednisone.","Prednisona em dose baixa."],["1y1o3rj1s","Which drug is used for giant cell arteritis besides steroids?","Tocilizumab (steroid-sparing).","Tocilizumabe."],["1phdnl21t","What is the screening needed before starting TNF inhibitors?","TB (PPD or IGRA), hepatitis B, hepatitis C.","Tuberculose e hepatites."],["1ol3nny3u","Which DMARD is safe in pregnancy?","Hydroxychloroquine, sulfasalazine, azathioprine (methotrexate and leflunomide are contraindicated).","Hidroxicloroquina."],["pv78o71ue","Which DMARD is contraindicated in pregnancy?","Methotrexate, leflunomide, mycophenolate, cyclophosphamide.","Metotrexato e leflunomida."],["1i0ir041x","Which drug causes pulmonary toxicity among DMARDs?","Methotrexate (pneumonitis).","Metotrexato."],["1oiyled15","Which drug causes hepatotoxicity requiring LFT monitoring in RA?","Methotrexate and leflunomide.","Metotrexato e leflunomida."],["iqfgu65iz","Which drug treats familial Mediterranean fever?","Colchicine.","Colchicina."],["rctcz11un","Which drug treats Behçet disease ulcers?","Colchicine, apremilast, glucocorticoids.","Colchicina ou apremilaste."],["hhhydr1dm","Which drug treats pemphigus vulgaris?","Systemic glucocorticoids and rituximab.","Corticoide e rituximabe."],["rbw5is1jd","Which drug treats bullous pemphigoid?","Potent topical or systemic steroids; doxycycline; dupilumab.","Corticoide."],["n3ewpd1dk","Which drug treats dermatitis herpetiformis?","Dapsone and gluten-free diet.","Dapsona e dieta sem glúten."],["1dsrgfi1t","Which drug treats rosacea?","Topical metronidazole, azelaic acid, ivermectin; oral doxycycline.","Metronidazol tópico."],["6z6gao109","Which drug treats severe hidradenitis suppurativa?","Adalimumab (and secukinumab).","Adalimumabe."],["1vh8uds13","What is the risk of high-dose glucocorticoids in children?","Growth suppression.","Atraso de crescimento."],["1c9fcunjv","Which analgesics are avoided in late pregnancy?","NSAIDs (premature PDA closure, oligohydramnios); acetaminophen preferred.","AINEs; preferir paracetamol."],["96yyv017h","Which analgesic is preferred in peptic ulcer disease?","Acetaminophen.","Paracetamol."],["1tltdwyrd","Which NSAID is used to close a PDA?","Indomethacin (or ibuprofen).","Indometacina."],["fitfw71cc","Which NSAID is given IV or IM for short-term severe pain?","Ketorolac (limit to 5 days due to renal and GI toxicity).","Cetorolaco."],["1eme88a39","What vitamin supplement is recommended with long-term glucocorticoids?","Calcium and vitamin D (with bisphosphonate if indicated).","Cálcio e vitamina D."]]}];
